"""Phase 8 - MCP: discovery + validasi manifest tool eksternal sebelum masuk registry governed.

Fail-closed: kelas/risiko tidak dikenal => EXTERNAL/HIGH (butuh approval). Tool tanpa handler,
skema, atau nama valid ditolak. Model tidak pernah melihat tool yang belum lolos validasi.
"""
from __future__ import annotations

import ast
import operator
import re
from datetime import datetime, timezone
from typing import Any, Callable

from app.governance.tools import GovernedToolRegistry, Risk, ToolClass, ToolSpec

_NAME = re.compile(r"^[a-z][a-z0-9_]{2,63}$")
_OBJ = {"type": "object"}


def register_manifest(registry: GovernedToolRegistry, manifest: list[dict[str, Any]],
                      handlers: dict[str, Callable[[dict[str, Any]], Any]]) -> dict[str, str]:
    """Return {tool_name: alasan_ditolak}. Tool valid didaftarkan; sisanya dilewati."""
    rejected: dict[str, str] = {}
    for i, t in enumerate(manifest):
        name = str(t.get("tool_name", f"#{i}"))
        try:
            if not _NAME.match(name):
                raise ValueError("nama tool tidak valid")
            if not t.get("description") or not isinstance(t.get("input_schema"), dict):
                raise ValueError("description/input_schema wajib")
            if name not in handlers:
                raise ValueError("handler tidak tersedia")
            try:
                cls = ToolClass(t.get("tool_class"))
            except ValueError:
                cls = ToolClass.EXTERNAL
            try:
                risk = Risk(t.get("risk"))
            except ValueError:
                risk = Risk.HIGH
            timeout = float(t.get("timeout_s", 10.0))
            if not 0 < timeout <= 120:
                raise ValueError("timeout_s harus 0..120")
            registry.register(ToolSpec(name, str(t["description"])[:500], t["input_schema"],
                                       t.get("output_schema") or _OBJ, cls, risk,
                                       str(t.get("permission", "")), timeout,
                                       bool(t.get("audit_required", True))), handlers[name])
        except (ValueError, TypeError) as exc:
            rejected[name] = str(exc)
    return rejected


_OPS = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul,
        ast.Div: operator.truediv, ast.Mod: operator.mod, ast.USub: operator.neg}


def safe_calc(expr: str) -> float:
    """Kalkulator aritmetika via AST (tanpa eval/pangkat) - bukan eksekusi kode arbitrer."""
    if len(expr) > 200:
        raise ValueError("ekspresi terlalu panjang")

    def ev(n: ast.AST) -> float:
        if isinstance(n, ast.Expression):
            return ev(n.body)
        if isinstance(n, ast.Constant) and isinstance(n.value, (int, float)) and not isinstance(n.value, bool):
            return n.value
        if isinstance(n, ast.BinOp) and type(n.op) in _OPS:
            return _OPS[type(n.op)](ev(n.left), ev(n.right))
        if isinstance(n, ast.UnaryOp) and type(n.op) in _OPS:
            return _OPS[type(n.op)](ev(n.operand))
        raise ValueError("ekspresi tidak diizinkan")
    return ev(ast.parse(expr, mode="eval"))


def register_builtin_tools(registry: GovernedToolRegistry) -> None:
    registry.register(
        ToolSpec("calculator", "Hitung ekspresi aritmetika sederhana",
                 {"type": "object", "required": ["expression"], "properties": {"expression": {"type": "string"}}},
                 {"type": "object", "required": ["result"]}, ToolClass.READ, Risk.LOW, timeout_s=2.0),
        lambda a: {"result": safe_calc(a["expression"])})
    registry.register(
        ToolSpec("current_time_utc", "Waktu UTC saat ini", _OBJ,
                 {"type": "object", "required": ["iso"]}, ToolClass.READ, Risk.LOW, timeout_s=1.0),
        lambda a: {"iso": datetime.now(timezone.utc).isoformat()})

"""Phase 9 - eksekusi proses terbatas: allowlist path absolut, tanpa shell, env minimal, timeout.

BUKAN isolasi tingkat OS (tanpa namespace/seccomp/container). Untuk kode tak tepercaya gunakan
container terpisah; modul ini hanya mencegah LLM menjalankan perintah di luar allowlist.
"""
from __future__ import annotations

import os
import subprocess
import tempfile
from dataclasses import dataclass


class SandboxDenied(PermissionError):
    pass


@dataclass
class SandboxResult:
    returncode: int | None
    stdout: str
    stderr: str
    timed_out: bool = False


def run_allowlisted(argv: list[str], *, allow: set[str], timeout_s: float = 5.0,
                    max_output: int = 20000) -> SandboxResult:
    if not argv or not all(isinstance(a, str) for a in argv):
        raise SandboxDenied("argv tidak valid")
    exe = argv[0]
    if not os.path.isabs(exe) or exe not in allow:
        raise SandboxDenied("executable tidak ada di allowlist")
    with tempfile.TemporaryDirectory() as cwd:
        try:
            p = subprocess.run(argv, shell=False, cwd=cwd, capture_output=True, timeout=timeout_s,
                               env={"PATH": "", "LANG": "C.UTF-8"}, stdin=subprocess.DEVNULL)
        except subprocess.TimeoutExpired as exc:
            return SandboxResult(None, "", (exc.stderr or b"").decode("utf-8", "replace")[:max_output], True)
    return SandboxResult(p.returncode, p.stdout.decode("utf-8", "replace")[:max_output],
                         p.stderr.decode("utf-8", "replace")[:max_output])

"""Tool governance: LLM tidak pernah menjalankan tool tanpa registry + policy + audit."""
from __future__ import annotations

import inspect
from collections.abc import Callable
from dataclasses import dataclass, field
from enum import Enum
from typing import Any

from app.approval.queue import ApprovalQueue
from app.core.hardening import CircuitBreaker, safe_call, validate_schema
from app.observability.metrics import metrics


class ToolClass(str, Enum):
    READ = "read"
    WRITE = "write"
    DELETE = "delete"
    EXECUTE = "execute"
    EXTERNAL = "external"


class Risk(str, Enum):
    LOW = "low"
    MEDIUM = "medium"
    HIGH = "high"
    CRITICAL = "critical"


class Decision(str, Enum):  # nilai sama dengan app.policy.schemas.PolicyDecision
    ALLOW = "ALLOW"
    REQUIRE_CONFIRMATION = "REQUIRE_CONFIRMATION"
    REQUIRE_HUMAN = "REQUIRE_HUMAN"
    DENY = "DENY"


@dataclass(frozen=True)
class ToolSpec:
    tool_name: str
    description: str
    input_schema: dict[str, Any]
    output_schema: dict[str, Any]
    tool_class: ToolClass
    risk: Risk
    permission: str = ""
    timeout_s: float = 10.0
    audit_required: bool = True


@dataclass
class ToolOutcome:
    status: str  # executed | pending_approval | denied | invalid_input | failed | unknown_tool
    tool: str
    output: Any = None
    error: str | None = None
    approval_id: str | None = None
    decision: str | None = None


PolicyFn = Callable[[ToolSpec, str], tuple[Decision, str]]


def default_tool_policy(spec: ToolSpec, role: str) -> tuple[Decision, str]:
    """Kebijakan bawaan: CRITICAL ditolak, HIGH butuh manusia, WRITE/EXECUTE/DELETE/EXTERNAL
    minimal konfirmasi. Fail-closed."""
    if spec.risk == Risk.CRITICAL:
        return Decision.DENY, "risiko kritis ditolak"
    if spec.risk == Risk.HIGH:
        return Decision.REQUIRE_HUMAN, "risiko tinggi butuh persetujuan manusia"
    if spec.tool_class in (ToolClass.DELETE, ToolClass.EXECUTE):
        return Decision.REQUIRE_HUMAN, f"tool {spec.tool_class.value} butuh persetujuan manusia"
    if spec.tool_class in (ToolClass.WRITE, ToolClass.EXTERNAL) or spec.risk == Risk.MEDIUM:
        return Decision.REQUIRE_CONFIRMATION, "perlu konfirmasi"
    return Decision.ALLOW, "read/low-risk"


@dataclass
class _Entry:
    spec: ToolSpec
    handler: Callable[[dict[str, Any]], Any]
    breaker: CircuitBreaker


class GovernedToolRegistry:
    def __init__(self, approvals: ApprovalQueue, policy: PolicyFn = default_tool_policy):
        self.approvals = approvals
        self.policy = policy
        self._tools: dict[str, _Entry] = {}

    def register(self, spec: ToolSpec, handler: Callable[[dict[str, Any]], Any]) -> None:
        if inspect.iscoroutinefunction(handler):
            raise TypeError("handler tool harus sync (jalankan async di luar registry)")
        if spec.tool_name in self._tools:
            raise ValueError(f"tool '{spec.tool_name}' sudah terdaftar")
        self._tools[spec.tool_name] = _Entry(spec, handler, CircuitBreaker(spec.tool_name))

    def visible_tools(self, role: str, permissions: set[str]) -> list[dict[str, Any]]:
        """Hanya tool yang boleh dilihat model: permission terpenuhi & bukan DENY."""
        out = []
        for e in self._tools.values():
            s = e.spec
            if s.permission and s.permission not in permissions:
                continue
            if self.policy(s, role)[0] == Decision.DENY:
                continue
            out.append({"name": s.tool_name, "description": s.description,
                        "input_schema": s.input_schema, "risk": s.risk.value,
                        "class": s.tool_class.value})
        return out

    def execute(self, name: str, args: dict[str, Any], *, role: str, permissions: set[str],
                requested_by: str, approval_id: str | None = None) -> ToolOutcome:
        audit = self.approvals.audit
        entry = self._tools.get(name)
        if entry is None:  # nama tool dari model tidak dipercaya
            audit.record("tool.unknown", tool=name, requested_by=requested_by)
            return ToolOutcome("unknown_tool", name, error="tool tidak terdaftar", decision=Decision.DENY.value)
        s = entry.spec
        if s.permission and s.permission not in permissions:
            audit.record("tool.denied", tool=name, reason="permission", requested_by=requested_by)
            return ToolOutcome("denied", name, error="permission tidak cukup", decision=Decision.DENY.value)
        decision, why = self.policy(s, role)
        audit.record("tool.policy", tool=name, decision=decision.value, reason=why,
                     risk=s.risk.value, requested_by=requested_by)
        if decision == Decision.DENY:
            return ToolOutcome("denied", name, error=why, decision=decision.value)
        errs = validate_schema(args, s.input_schema)
        if errs:
            return ToolOutcome("invalid_input", name, error="; ".join(errs), decision=decision.value)
        if decision != Decision.ALLOW:
            granted = bool(approval_id) and self.approvals.consume(approval_id, {"tool": name, "args": args})
            if not granted:
                req = self.approvals.submit(
                    "tool_call", {"tool": name, "args": args}, risk=s.risk.value,
                    requested_by=requested_by, summary={"tool": name, "class": s.tool_class.value, "reason": why})
                return ToolOutcome("pending_approval", name, approval_id=req.approval_id,
                                   decision=decision.value, error=why)
        res = safe_call(entry.handler, args, timeout_s=s.timeout_s, breaker=entry.breaker)
        metrics.incr(f"tool.{name}.{'ok' if res.ok else 'fail'}")
        if s.audit_required:
            audit.record("tool.executed", tool=name, ok=res.ok, error=res.error,
                         duration_ms=round(res.duration_ms, 2), requested_by=requested_by)
        if not res.ok:
            return ToolOutcome("failed", name, error=f"{res.error_type}: {res.error}", decision=decision.value)
        oerrs = validate_schema(res.value, s.output_schema)
        if oerrs:
            return ToolOutcome("failed", name, error="output tidak sesuai skema: " + "; ".join(oerrs),
                               decision=decision.value)
        return ToolOutcome("executed", name, output=res.value, decision=decision.value)

"""Phase 19 - gerbang pengembangan V1.x: hanya change request approved + test/rollback plan + baseline.
Modul ini tidak menjalankan git; ia memvalidasi syarat dan mencatat versi (V1.0 tidak pernah dihapus)."""
from __future__ import annotations

import json
import re
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path

from app.approval.change_request import ChangeRequest
from app.research.improvement import Proposal

BRANCH_RE = re.compile(r"^feature/improvement-\d{4}$")
_VERSION_RE = re.compile(r"^\d+\.\d+(-rc\d+)?$")
_TRANSITIONS = {"candidate": {"validated", "abandoned"}, "validated": {"released", "abandoned"},
                "released": {"stable", "rolled_back"}, "stable": set(), "rolled_back": set(), "abandoned": set()}


class GateBlocked(RuntimeError):
    def __init__(self, blockers: list[str]):
        super().__init__("; ".join(blockers))
        self.blockers = blockers


class VersionRegistry:
    def __init__(self, path: Path):
        self.path = Path(path)
        if self.path.exists():
            self.data = json.loads(self.path.read_text("utf-8"))
        else:
            self.data = {"1.0": {"status": "stable", "parent": None, "change_requests": [],
                                 "created_at": datetime.now(timezone.utc).isoformat()}}
            self._save()

    def _save(self) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self.path.write_text(json.dumps(self.data, indent=2), "utf-8")

    def register(self, version: str, parent: str, change_request_id: str) -> None:
        if not _VERSION_RE.match(version):
            raise ValueError("format versi tidak valid")
        if version in self.data:
            raise ValueError("versi sudah ada (tidak boleh ditimpa)")
        if parent not in self.data:
            raise ValueError("parent tidak dikenal")
        self.data[version] = {"status": "candidate", "parent": parent, "change_requests": [change_request_id],
                              "created_at": datetime.now(timezone.utc).isoformat()}
        self._save()

    def transition(self, version: str, status: str) -> None:
        cur = self.data[version]["status"]
        if status not in _TRANSITIONS.get(cur, set()):
            raise ValueError(f"transisi {cur} -> {status} tidak diizinkan")
        self.data[version]["status"] = status
        self._save()

    def status(self, version: str) -> str | None:
        return self.data.get(version, {}).get("status")


@dataclass
class DevBranch:
    name: str
    target_version: str
    git_commands: list[str]


def branch_name(proposal_id: str) -> str:
    m = re.fullmatch(r"PROPOSAL-(\d{4})", proposal_id)
    if not m:
        raise ValueError("proposal_id tidak valid")
    return f"feature/improvement-{m.group(1)}"


def check(cr: ChangeRequest, p: Proposal, baseline_name: str | None) -> list[str]:
    b: list[str] = []
    if cr.status != "open":
        b.append("change request tidak berstatus open")
    if cr.proposal_id != p.proposal_id:
        b.append("change request tidak cocok dengan proposal")
    if not p.test_plan.strip():
        b.append("test plan kosong")
    if not p.rollback_plan.strip():
        b.append("rollback plan kosong")
    if not baseline_name:
        b.append("baseline evaluasi tidak tersedia")
    return b


def start(cr: ChangeRequest, p: Proposal, baseline_name: str | None, registry: VersionRegistry,
          target_version: str, parent: str = "1.0") -> DevBranch:
    blockers = check(cr, p, baseline_name)
    if blockers:
        raise GateBlocked(blockers)
    name = branch_name(p.proposal_id)
    registry.register(target_version, parent, cr.change_request_id)
    cr.status = "in_development"
    return DevBranch(name, target_version, [f"git checkout -b {name} v{parent}",
                                            "# lakukan perubahan, jalankan tes + evaluasi, buka review",
                                            f"git tag v{target_version}  # setelah lolos Phase 20"])

from typing import Protocol, Any
class LLMProviderProtocol(Protocol):
    def generate(self, request: Any) -> Any: ...

from typing import List

def chunk_text(text: str, chunk_size: int = 512, overlap: int = 64) -> List[str]:
    if chunk_size <= 0: raise ValueError('chunk_size must be positive')
    overlap = max(0, min(overlap, chunk_size - 1))
    if not text: return []
    out=[]; start=0
    while start < len(text):
        end=min(len(text), start+chunk_size); out.append(text[start:end])
        if end == len(text): break
        start=end-overlap
    return out

class Chunker:
    def __init__(self, chunk_size=512, overlap=64): self.chunk_size=chunk_size; self.overlap=overlap
    def chunk(self, text): return chunk_text(text, self.chunk_size, self.overlap)

SentenceChunker = Chunker

ParagraphChunker = Chunker

def get_chunker(strategy="sentence", chunk_size=512, overlap=64): return Chunker(chunk_size, overlap)

"""
Embeddings - Generate embedding dari teks.
Provider-independent: mendukung multiple embedding model.
"""
from typing import List, Optional
import numpy as np


class EmbeddingProvider:
    """
    Abstraksi provider embedding.
    Mendukung multiple backend: sentence-transformers, OpenAI, dll.
    """

    def __init__(self, model: str = "sentence-transformers/all-MiniLM-L6-v2"):
        self._model = model
        self._dimension = self._detect_dimension(model)

    def _detect_dimension(self, model: str) -> int:
        """Detect dimensi embedding berdasarkan model."""
        known_dims = {
            "sentence-transformers/all-MiniLM-L6-v2": 384,
            "sentence-transformers/all-mpnet-base-v2": 768,
            "sentence-transformers/all-T5-base": 768,
            "BAAI/bge-small-en-v1.5": 384,
            "BAAI/bge-base-en-v1.5": 768,
            "text-embedding-ada-002": 1536,
            "text-embedding-3-small": 1536,
            "text-embedding-3-large": 3072,
        }
        return known_dims.get(model, 384)

    @property
    def model(self) -> str:
        return self._model

    @property
    def dimension(self) -> int:
        return self._dimension

    def embed(self, text: str) -> List[float]:
        """Generate embedding dari teks."""
        raise NotImplementedError("Subclass harus implement embed()")

    def embed_batch(self, texts: List[str]) -> List[List[float]]:
        """Generate embedding batch."""
        return [self.embed(text) for text in texts]

    def embed_documents(self, texts: List[str], batch_size: int = 32) -> List[List[float]]:
        """Embed multiple documents dengan chunking."""
        results = []
        for i in range(0, len(texts), batch_size):
            batch = texts[i:i + batch_size]
            results.extend(self.embed_batch(batch))
        return results


class SentenceTransformerEmbedder(EmbeddingProvider):
    """
    Embedder menggunakan Sentence Transformers (Hugging Face).
    Membutuhkan: pip install sentence-transformers
    """

    def __init__(self, model: str = "sentence-transformers/all-MiniLM-L6-v2"):
        super().__init__(model)
        self._client = None
        self._load_model(model)

    def _load_model(self, model: str) -> None:
        """Load model sentence transformers."""
        try:
            from sentence_transformers import SentenceTransformer
            self._client = SentenceTransformer(model)
        except ImportError:
            self._client = None
            print(f"Warning: sentence-transformers not installed. "
                  f"Install with: pip install sentence-transformers")

    def embed(self, text: str) -> List[float]:
        """Generate embedding menggunakan sentence transformers."""
        if self._client is None:
            # Fallback: hash-based embedding
            return self._fallback_embedding(text)

        embedding = self._client.encode(text)
        return embedding.tolist()

    def embed_batch(self, texts: List[str]) -> List[List[float]]:
        """Embed batch menggunakan sentence transformers."""
        if self._client is None:
            return [self._fallback_embedding(text) for text in texts]

        embeddings = self._client.encode(texts)
        return embeddings.tolist()

    def _fallback_embedding(self, text: str) -> List[float]:
        """Fallback embedding menggunakan hash."""
        import hashlib
        hash_bytes = hashlib.md5(text.encode()).digest()
        dim = self._dimension
        result = []
        for i in range(dim):
            if i < len(hash_bytes):
                result.append(float(hash_bytes[i]) / 255.0)
            else:
                result.append(0.0)
        return result


class OpenAIEmbeddingProvider(EmbeddingProvider):
    """
    Embedder menggunakan OpenAI API.
    Membutuhkan API key.
    """

    def __init__(
        self,
        model: str = "text-embedding-ada-002",
        api_key: Optional[str] = None,
        base_url: Optional[str] = None,
    ):
        super().__init__(model)
        self._api_key = api_key
        self._base_url = base_url

    def embed(self, text: str) -> List[float]:
        """Embed menggunakan OpenAI API."""
        import openai

        client = openai.OpenAI(
            api_key=self._api_key or "",
            base_url=self._base_url,
        )

        response = client.embeddings.create(
            input=text,
            model=self._model,
        )

        return response.data[0].embedding


class MockEmbeddingProvider(EmbeddingProvider):
    """
    Mock embedding provider untuk testing.
    Menghasilkan embedding acak yang deterministik berdasarkan teks.
    """

    def __init__(self, dimension: int = 384):
        # Gunakan model generic tapi kita set dimension manual
        super().__init__("mock")
        self._dimension = dimension

    def embed(self, text: str) -> List[float]:
        """Generate pseudo-embedding deterministik."""
        import hashlib
        import struct

        hash_bytes = hashlib.md5(text.encode()).digest()
        result = []
        for i in range(self._dimension):
            if i < len(hash_bytes):
                val = float(hash_bytes[i]) / 255.0
            else:
                # Generate dari hash yang lebih panjang
                combined = hashlib.md5(f"{text}_{i}".encode()).digest()
                val = float(combined[i % len(combined)]) / 255.0
            result.append(val)
        return result


class EmbeddingService:
    """
    Service yang menggabungkan multiple embedding provider.
    Provider-independent: bisa swap provider tanpa mengubah kode.
    """

    def __init__(
        self,
        provider: Optional[EmbeddingProvider] = None,
        config: Optional[dict] = None,
    ):
