}

MAX_FILE_SIZE_MB = 50
MIN_TEXT_LENGTH = 40

CHUNK_SIZE = 900
CHUNK_OVERLAP = 120


def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat()


def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for block in iter(lambda: f.read(1024 * 1024), b""):
            h.update(block)
    return h.hexdigest()


def sha256_text(text: str) -> str:
    return hashlib.sha256(
        text.encode("utf-8", errors="ignore")
    ).hexdigest()


def normalize_text(text: str) -> str:
    text = text.replace("\x00", " ")
    text = text.replace("\r\n", "\n")
    text = text.replace("\r", "\n")

    lines = []
    for line in text.split("\n"):
        line = re.sub(r"[ \t]+", " ", line).strip()
        if line:
            lines.append(line)

    text = "\n".join(lines)
    text = re.sub(r"\n{3,}", "\n\n", text)

    return text.strip()


def load_txt(path: Path) -> str:
    return path.read_text(
        encoding="utf-8",
        errors="replace",
    )


def load_json(path: Path) -> str:
    obj = json.loads(
        path.read_text(
            encoding="utf-8",
            errors="replace",
        )
    )

    if isinstance(obj, str):
        return obj

    return json.dumps(
        obj,
        ensure_ascii=False,
        indent=2,
    )


def load_docx(path: Path) -> str:
    try:
        from docx import Document
    except ImportError as exc:
        raise RuntimeError(
            "python-docx belum terinstall. "
            "Install dengan: python -m pip install python-docx"
        ) from exc

    document = Document(str(path))

    paragraphs = [
        p.text.strip()
        for p in document.paragraphs
        if p.text.strip()
    ]

    tables = []

    for table in document.tables:
        for row in table.rows:
            values = [
                cell.text.strip()
                for cell in row.cells
            ]
            values = [v for v in values if v]
            if values:
                tables.append(" | ".join(values))

    return "\n".join(paragraphs + tables)


def load_pdf(path: Path) -> str:
    try:
        from pypdf import PdfReader
    except ImportError as exc:
        raise RuntimeError(
            "pypdf belum terinstall. "
            "Install dengan: python -m pip install pypdf"
        ) from exc

    reader = PdfReader(str(path))

    pages = []

    for index, page in enumerate(reader.pages, start=1):
        text = page.extract_text() or ""

        text = normalize_text(text)

        if text:
            pages.append(
                f"[PAGE {index}]\n{text}"
            )

    return "\n\n".join(pages)


def load_html(path: Path) -> str:
    raw = path.read_text(
        encoding="utf-8",
        errors="replace",
    )

    try:
        from bs4 import BeautifulSoup
    except ImportError:
        text = re.sub(
            r"<script.*?</script>",
            " ",
            raw,
            flags=re.I | re.S,
        )
        text = re.sub(
            r"<style.*?</style>",
            " ",
            text,
            flags=re.I | re.S,
        )
        text = re.sub(r"<[^>]+>", " ", text)
        return normalize_text(text)

    soup = BeautifulSoup(raw, "html.parser")

    for tag in soup(
        ["script", "style", "noscript"]
    ):
        tag.decompose()

    return soup.get_text("\n")


def extract_text(path: Path) -> str:
    suffix = path.suffix.lower()

    if suffix in {".txt", ".md"}:
        return load_txt(path)

    if suffix == ".json":
        return load_json(path)

    if suffix == ".docx":
        return load_docx(path)

    if suffix == ".pdf":
        return load_pdf(path)

    if suffix in {".html", ".htm"}:
        return load_html(path)

    raise ValueError(
        f"Format tidak didukung: {suffix}"
    )


def classify_source(relative_path: Path) -> dict:
    parts = [
        p.lower()
        for p in relative_path.parts
    ]

    service = "general"

    mapping = {
        "ktp_el": "ktp_el",
        "ktp": "ktp_el",
        "kartu_keluarga": "kartu_keluarga",
        "kk": "kartu_keluarga",
        "kia": "kia",
        "akta_kelahiran": "akta_kelahiran",
        "akta_kematian": "akta_kematian",
        "perkawinan": "perkawinan",
        "perceraian": "perceraian",
        "pindah_datang": "pindah_datang",
        "perubahan_data": "perubahan_data",
        "layanan_online": "layanan_online",
    }

    for part in parts:
        if part in mapping:
            service = mapping[part]
            break

    content_type = "general"

    name = relative_path.stem.lower()

    if any(
        token in name
        for token in [
            "syarat",
            "persyaratan",
            "requirement",
        ]
    ):
        content_type = "requirements"

    elif any(
        token in name
        for token in [
            "prosedur",
            "cara",
            "alur",
            "proses",
        ]
    ):
        content_type = "procedure"

    elif any(
        token in name
        for token in [
            "biaya",
            "tarif",
        ]
    ):
        content_type = "fee"

    elif any(
        token in name
        for token in [
            "waktu",
            "durasi",
            "lama",
        ]
    ):
        content_type = "processing_time"

    elif any(
        token in name
        for token in [
            "status",
            "cek",
            "tracking",
        ]
    ):
        content_type = "status"

    return {
        "domain": "kependudukan",
        "service": service,
        "content_type": content_type,
    }


def chunk_text(
    text: str,
    size: int = CHUNK_SIZE,
    overlap: int = CHUNK_OVERLAP,
) -> list[str]:

    text = normalize_text(text)

    if not text:
        return []

    paragraphs = [
        p.strip()
        for p in re.split(
            r"\n\s*\n",
            text,
        )
        if p.strip()
    ]

    chunks = []
    current = ""

    for paragraph in paragraphs:

        if len(paragraph) > size:
            if current:
                chunks.append(current)
                current = ""

            start = 0

            while start < len(paragraph):
                end = min(
                    start + size,
                    len(paragraph),
                )

                piece = paragraph[start:end].strip()

                if piece:
                    chunks.append(piece)

                if end >= len(paragraph):
                    break

                start = max(
                    end - overlap,
                    start + 1,
                )

            continue

        candidate = (
            paragraph
            if not current
            else current + "\n\n" + paragraph
        )

        if len(candidate) <= size:
            current = candidate
        else:
            if current:
                chunks.append(current)

            tail = ""

            if overlap > 0 and current:
                tail = current[-overlap:]

            current = (
                tail + "\n\n" + paragraph
                if tail
                else paragraph
            )

    if current:
        chunks.append(current)

    return [
        normalize_text(chunk)
        for chunk in chunks
        if len(normalize_text(chunk)) >= 20
    ]


def make_document_id(file_hash: str) -> str:
    return "DOC-" + file_hash[:16].upper()


def make_chunk_id(
    document_id: str,
    index: int,
    text: str,
) -> str:
    digest = sha256_text(
        f"{document_id}:{index}:{text}"
    )

    return "CHUNK-" + digest[:20].upper()


