class ProductionKnowledgeBase:

    def __init__(
        self,
        db_path: Path = DB_PATH,
    ):
        self.db_path = db_path

        db_path.parent.mkdir(
            parents=True,
            exist_ok=True,
        )

        self.conn = sqlite3.connect(
            str(db_path)
        )

        self.conn.row_factory = sqlite3.Row

        self._initialize()

    def _initialize(self):

        self.conn.executescript(
            """
            PRAGMA journal_mode=WAL;
            PRAGMA foreign_keys=ON;

            CREATE TABLE IF NOT EXISTS documents (
                document_id TEXT PRIMARY KEY,
                title TEXT NOT NULL,
                source_file TEXT NOT NULL,
                source_hash TEXT NOT NULL,
                source_type TEXT NOT NULL,
                domain TEXT NOT NULL,
                service TEXT NOT NULL,
                content_type TEXT NOT NULL,
                text_length INTEGER NOT NULL,
                chunk_count INTEGER NOT NULL,
                ingested_at TEXT NOT NULL,
                active INTEGER NOT NULL DEFAULT 1
            );

            CREATE TABLE IF NOT EXISTS chunks (
                chunk_id TEXT PRIMARY KEY,
                document_id TEXT NOT NULL,
                chunk_index INTEGER NOT NULL,
                text TEXT NOT NULL,
                text_hash TEXT NOT NULL,
                token_estimate INTEGER NOT NULL,
                created_at TEXT NOT NULL,
                FOREIGN KEY(document_id)
                    REFERENCES documents(document_id)
                    ON DELETE CASCADE
            );

            CREATE INDEX IF NOT EXISTS
                idx_chunks_document
                ON chunks(document_id);

            CREATE INDEX IF NOT EXISTS
                idx_documents_service
                ON documents(service);

            CREATE INDEX IF NOT EXISTS
                idx_documents_content_type
                ON documents(content_type);

            CREATE VIRTUAL TABLE IF NOT EXISTS
                chunks_fts USING fts5(
                    chunk_id UNINDEXED,
                    document_id UNINDEXED,
                    text,
                    tokenize='unicode61'
                );

            CREATE TABLE IF NOT EXISTS ingestion_log (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                source_file TEXT,
                source_hash TEXT,
                status TEXT,
                message TEXT,
                created_at TEXT
            );
            """
        )

        self.conn.commit()

    def close(self):
        self.conn.close()

    def document_exists(
        self,
        source_hash: str,
    ) -> bool:

        row = self.conn.execute(
            """
            SELECT document_id
            FROM documents
            WHERE source_hash = ?
              AND active = 1
            LIMIT 1
            """,
            (source_hash,),
        ).fetchone()

        return row is not None

    def ingest_file(
        self,
        path: Path,
        source_root: Path,
    ) -> dict:

        relative = path.relative_to(
            source_root
        )

        source_hash = sha256_file(path)

        if self.document_exists(source_hash):
            return {
                "status": "SKIP",
                "file": str(relative),
                "reason": "already_ingested",
            }

        metadata = classify_source(relative)

        title = path.stem.replace(
            "_",
            " ",
        ).replace(
            "-",
            " ",
        ).strip()

        document_id = make_document_id(
            source_hash
        )

        text = normalize_text(
            extract_text(path)
        )

        if len(text) < MIN_TEXT_LENGTH:
            raise ValueError(
                f"Isi dokumen terlalu pendek: "
                f"{len(text)} karakter"
            )

        chunks = chunk_text(text)

        if not chunks:
            raise ValueError(
                "Tidak menghasilkan chunk."
            )

        now = utc_now()

        self.conn.execute(
            """
            INSERT INTO documents (
                document_id,
                title,
                source_file,
                source_hash,
                source_type,
                domain,
                service,
                content_type,
                text_length,
                chunk_count,
                ingested_at,
                active
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1)
            """,
            (
                document_id,
                title,
                str(relative),
                source_hash,
                "file",
                metadata["domain"],
                metadata["service"],
                metadata["content_type"],
                len(text),
                len(chunks),
                now,
            ),
        )

        for index, chunk in enumerate(
            chunks
        ):

            chunk_id = make_chunk_id(
                document_id,
                index,
                chunk,
            )

            token_estimate = max(
                1,
                len(
                    re.findall(
                        r"\S+",
                        chunk,
                    )
                ),
            )

            self.conn.execute(
                """
                INSERT INTO chunks (
                    chunk_id,
                    document_id,
                    chunk_index,
                    text,
                    text_hash,
                    token_estimate,
                    created_at
                )
                VALUES (?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    chunk_id,
                    document_id,
                    index,
                    chunk,
                    sha256_text(chunk),
                    token_estimate,
                    now,
                ),
            )

            self.conn.execute(
                """
                INSERT INTO chunks_fts (
                    chunk_id,
                    document_id,
                    text
                )
                VALUES (?, ?, ?)
                """,
                (
                    chunk_id,
                    document_id,
                    chunk,
                ),
            )

        self.conn.execute(
            """
            INSERT INTO ingestion_log (
                source_file,
                source_hash,
                status,
                message,
                created_at
            )
            VALUES (?, ?, ?, ?, ?)
            """,
            (
                str(relative),
                source_hash,
                "SUCCESS",
                f"{len(chunks)} chunks",
                now,
            ),
        )

        self.conn.commit()

        return {
            "status": "INGESTED",
            "file": str(relative),
            "document_id": document_id,
            "chunks": len(chunks),
            "characters": len(text),
            "service": metadata["service"],
            "content_type": metadata["content_type"],
        }

    def search(
        self,
        query: str,
        limit: int = 5,
    ) -> list[dict]:

        query = normalize_text(query)

        if not query:
            return []

        safe_terms = re.findall(
            r"[\w-]+",
            query,
            flags=re.UNICODE,
        )

        if not safe_terms:
            return []

        fts_query = " OR ".join(
            f'"{term}"'
            for term in safe_terms
        )

        rows = self.conn.execute(
            """
            SELECT
                f.chunk_id,
                f.document_id,
                f.text,
                d.title,
                d.source_file,
                d.service,
                d.content_type
            FROM chunks_fts f
            JOIN chunks c
              ON c.chunk_id = f.chunk_id
            JOIN documents d
              ON d.document_id = f.document_id
            WHERE chunks_fts MATCH ?
              AND d.active = 1
            LIMIT ?
            """,
            (
                fts_query,
                int(limit),
            ),
        ).fetchall()

        return [
            dict(row)
            for row in rows
        ]

    def stats(self) -> dict:

        documents = self.conn.execute(
            """
            SELECT COUNT(*)
            FROM documents
            WHERE active = 1
            """
        ).fetchone()[0]

        chunks = self.conn.execute(
            """
            SELECT COUNT(*)
            FROM chunks
            """
        ).fetchone()[0]

        services = self.conn.execute(
            """
            SELECT service, COUNT(*)
            FROM documents
            WHERE active = 1
            GROUP BY service
            ORDER BY service
            """
        ).fetchall()

        content_types = self.conn.execute(
            """
            SELECT content_type, COUNT(*)
            FROM documents
            WHERE active = 1
            GROUP BY content_type
            ORDER BY content_type
            """
        ).fetchall()

        return {
            "database": str(self.db_path),
            "documents": documents,
            "chunks": chunks,
            "services": {
                row[0]: row[1]
                for row in services
            },
            "content_types": {
                row[0]: row[1]
                for row in content_types
            },
        }


