def backup_database():

    if not DB_PATH.exists():
        return None

    timestamp = datetime.now().strftime(
        "%Y%m%d_%H%M%S"
    )

    backup = (
        KB_ROOT
        / f"production_knowledge_backup_{timestamp}.db"
    )

    shutil.copy2(
        DB_PATH,
        backup,
    )

    return backup


def validate_file(
    path: Path,
) -> tuple[bool, str]:

    if path.suffix.lower() not in SUPPORTED_EXTENSIONS:
        return False, "unsupported_extension"

    if not path.is_file():
        return False, "not_file"

    size = path.stat().st_size

    if size == 0:
        return False, "empty_file"

    if size > MAX_FILE_SIZE_MB * 1024 * 1024:
        return False, "file_too_large"

    return True, "ok"


def build_manifest(
    kb: ProductionKnowledgeBase,
):

    stats = kb.stats()

    manifest = {
        "name": "Nusantara AI Production Knowledge Base",
        "version": "1.0.0",
        "generated_at": utc_now(),
        "database": str(
            DB_PATH.relative_to(ROOT)
        ),
        "source_root": str(
            SOURCE_ROOT.relative_to(ROOT)
        ),
        "chunking": {
            "chunk_size": CHUNK_SIZE,
            "chunk_overlap": CHUNK_OVERLAP,
        },
        "supported_extensions": sorted(
            SUPPORTED_EXTENSIONS
        ),
        "stats": stats,
    }

    MANIFEST_PATH.write_text(
        json.dumps(
            manifest,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )


def ingest_all() -> int:

    validate_environment()

    backup = backup_database()

    kb = ProductionKnowledgeBase()

    results = []

    try:

        files = sorted(
            path
            for path in SOURCE_ROOT.rglob("*")
            if path.is_file()
        )

        for path in files:

            valid, reason = validate_file(
                path
            )

            if not valid:
                results.append(
                    {
                        "status": "QUARANTINE",
                        "file": str(
                            path.relative_to(
                                SOURCE_ROOT
                            )
                        ),
                        "reason": reason,
                    }
                )

                continue

            try:

                result = kb.ingest_file(
                    path,
                    SOURCE_ROOT,
                )

                results.append(result)

            except Exception as exc:

                results.append(
                    {
                        "status": "ERROR",
                        "file": str(
                            path.relative_to(
                                SOURCE_ROOT
                            )
                        ),
                        "reason": str(exc),
                    }
                )

        build_manifest(kb)

        print()
        print("=" * 72)
        print("NUSANTARA PRODUCTION KNOWLEDGE BASE")
        print("=" * 72)

        for result in results:
            print(
                f"[{result['status']}] "
                f"{result['file']}"
            )

        stats = kb.stats()

        print()
        print(
            f"DOCUMENTS : {stats['documents']}"
        )
        print(
            f"CHUNKS    : {stats['chunks']}"
        )

        print()
        print("SERVICES")

        for key, value in stats[
            "services"
        ].items():
            print(
                f"  {key}: {value}"
            )

        print()
        print("CONTENT TYPES")

        for key, value in stats[
            "content_types"
        ].items():
