from __future__ import annotations

from typing import Any

from app.language.intent import IntentClassifier
from app.language.semantic.semantic_intent import (
    SemanticIntentEngine,
)


class IntentFusion:
    """
    Intent Fusion Nusantara Core.

    Menggabungkan:
    - Rule Intent
    - IndoBERT Semantic Intent
    - Context Conflict Resolution

    intent.py tidak dimodifikasi.
    """

    SEMANTIC_MIN_THRESHOLD = 0.70
    SEMANTIC_MARGIN = 0.08

    # Intent yang sangat sensitif terhadap konteks.
    REQUIREMENT_INTENT = "ask_document_requirements"
    ISSUANCE_INTENT = "request_document_issuance"
    STATUS_INTENT = "ask_document_status"
    MISSING_INTENT = "report_missing_document"
    TECHNICAL_ISSUE_INTENT = "report_technical_issue"
    TECHNICAL_HELP_INTENT = "request_technical_help"

    def __init__(
        self,
        rule_classifier: IntentClassifier | None = None,
        semantic_engine: SemanticIntentEngine | None = None,
    ) -> None:

        self.rule_classifier = (
            rule_classifier
            or IntentClassifier()
        )

        self.semantic_engine = (
            semantic_engine
            or SemanticIntentEngine()
        )

    @staticmethod
    def _extract_value(
        result: Any,
        key: str,
        default: Any = None,
    ) -> Any:

        if isinstance(result, dict):
            return result.get(key, default)

        return getattr(
            result,
            key,
            default,
        )

    def _normalize_rule_result(
        self,
        result: Any,
    ) -> dict[str, Any]:

        intent = self._extract_value(
            result,
            "intent",
            "unknown",
        )

        confidence = self._extract_value(
            result,
            "confidence",
            0.0,
        )

        try:
            confidence = float(confidence)
        except (TypeError, ValueError):
            confidence = 0.0

        return {
            "intent": intent or "unknown",
            "confidence": confidence,
            "raw": result,
        }

    @staticmethod
    def _has_requirement_context(
        text: str,
    ) -> bool:

        keywords = (
            "syarat",
            "syaratnya",
            "persyaratan",
            "berkas",
            "dokumen yang diperlukan",
            "dokumen yang harus",
            "dokumen apa",
            "berkas apa",
            "yang diperlukan",
            "yang dibutuhkan",
            "yang harus disiapkan",
            "harus saya siapkan",
            "perlu disiapkan",
        )

        return any(
            keyword in text
            for keyword in keywords
        )

    @staticmethod
    def _has_issuance_context(
        text: str,
    ) -> bool:

        keywords = (
            "membuat",
            "buat",
            "mengurus",
            "urus",
            "mengajukan",
            "ajukan",
            "penerbitan",
            "pengajuan",
            "mendaftarkan",
            "daftar",
        )

        return any(
            keyword in text
            for keyword in keywords
        )

    @staticmethod
    def _has_status_context(
        text: str,
    ) -> bool:

        keywords = (
            "status",
            "sudah jadi",
            "sudah selesai",
            "belum selesai",
            "sampai mana",
            "cek pengajuan",
            "cek status",
        )

        return any(
            keyword in text
            for keyword in keywords
        )

    @staticmethod
    def _has_missing_context(
        text: str,
    ) -> bool:

        keywords = (
            "belum menerima",
            "belum saya terima",
            "belum sampai",
            "tidak sampai",
            "belum diterima",
            "hilang",
        )

        return any(
            keyword in text
            for keyword in keywords
        )

    @staticmethod
    def _has_technical_problem_context(
        text: str,
    ) -> bool:

        keywords = (
            "error",
            "tidak bisa",
            "gagal",
            "tidak dapat",
            "bermasalah",
            "tidak berjalan",
            "tidak bisa dibuka",
            "tidak bisa login",
        )

        return any(
            keyword in text
            for keyword in keywords
        )

    @staticmethod
    def _has_technical_help_context(
        text: str,
    ) -> bool:

        keywords = (
            "bagaimana cara",
            "cara menggunakan",
            "cara login",
            "cara upload",
            "tolong bantu",
            "ajari saya",
            "bagaimana menggunakan",
        )

        return any(
            keyword in text
            for keyword in keywords
        )

    def _resolve_context_conflict(
        self,
        text: str,
        rule_intent: str,
        rule_confidence: float,
        semantic_intent: str,
        semantic_confidence: float,
    ) -> dict[str, Any] | None:
        """
        Menangani konflik intent yang secara semantik
        memiliki konteks khusus.

        Return None jika tidak ada conflict khusus.
        """

        normalized = text.lower().strip()

        # ==================================================
        # REQUIREMENTS vs ISSUANCE
        # ==================================================

        if (
            semantic_intent
            == self.REQUIREMENT_INTENT
            and rule_intent
            == self.ISSUANCE_INTENT
            and self._has_requirement_context(
                normalized
            )
        ):

            if semantic_confidence >= 0.78:

                return {
                    "intent": self.REQUIREMENT_INTENT,
                    "confidence": semantic_confidence,
                    "decision": (
                        "semantic_requirement_override"
                    ),
                    "reason": (
                        "Konteks kalimat menunjukkan "
                        "permintaan persyaratan/berkas."
                    ),
                }

        # ==================================================
        # ISSUANCE vs TECHNICAL HELP
        # ==================================================

        if (
            semantic_intent
            == self.ISSUANCE_INTENT
            and rule_intent
            == self.TECHNICAL_HELP_INTENT
            and self._has_issuance_context(
                normalized
            )
            and not self._has_technical_problem_context(
                normalized
            )
        ):

            if semantic_confidence >= 0.78:

                return {
                    "intent": self.ISSUANCE_INTENT,
                    "confidence": semantic_confidence,
                    "decision": (
                        "semantic_issuance_override"
                    ),
                    "reason": (
                        "Konteks menunjukkan "
                        "pengajuan/pembuatan dokumen."
                    ),
                }

        # ==================================================
        # MISSING vs STATUS
        # ==================================================

        if (
            semantic_intent
            == self.MISSING_INTENT
            and rule_intent
            == self.STATUS_INTENT
            and self._has_missing_context(
                normalized
            )
        ):

            if semantic_confidence >= 0.75:

                return {
                    "intent": self.MISSING_INTENT,
                    "confidence": semantic_confidence,
                    "decision": (
                        "semantic_missing_override"
                    ),
                    "reason": (
                        "Konteks menunjukkan "
                        "dokumen belum diterima."
                    ),
                }

        # ==================================================
        # TECHNICAL ISSUE vs TECHNICAL HELP
        # ==================================================

        if (
            semantic_intent
            == self.TECHNICAL_ISSUE_INTENT
            and rule_intent
            == self.TECHNICAL_HELP_INTENT
            and self._has_technical_problem_context(
                normalized
            )
        ):

            if semantic_confidence >= 0.70:

                return {
                    "intent": (
                        self.TECHNICAL_ISSUE_INTENT
                    ),
                    "confidence": semantic_confidence,
                    "decision": (
                        "semantic_technical_issue_override"
                    ),
                    "reason": (
                        "Konteks menunjukkan "
                        "masalah teknis."
                    ),
                }

        return None

    def classify(
        self,
        text: str,
    ) -> dict[str, Any]:

        text = str(text).strip()

        if not text:
            return {
                "ok": False,
                "engine": "intent-fusion",
                "error": "text wajib diisi",
            }

        # ==================================================
        # RULE
        # ==================================================

        rule_raw = self.rule_classifier.classify(text)

        rule = self._normalize_rule_result(
            rule_raw
        )

        rule_intent = rule["intent"]
        rule_confidence = rule["confidence"]

        # ==================================================
        # SEMANTIC
        # ==================================================

        semantic = self.semantic_engine.classify(
            text
        )

        if not semantic.get("ok"):

            return {
                "ok": True,
                "engine": "intent-fusion",
                "text": text,
                "intent": rule_intent,
                "confidence": rule_confidence,
                "decision": "rule_fallback",
                "rule": {
                    "intent": rule_intent,
                    "confidence": rule_confidence,
                },
                "semantic": semantic,
            }

        semantic_intent = semantic.get(
            "intent",
            "unknown",
        )

        semantic_confidence = float(
            semantic.get(
                "confidence",
                0.0,
            )
        )

        # ==================================================
        # CONTEXT CONFLICT RESOLUTION
        # ==================================================

        context_decision = (
            self._resolve_context_conflict(
                text=text,
                rule_intent=rule_intent,
                rule_confidence=rule_confidence,
                semantic_intent=semantic_intent,
                semantic_confidence=semantic_confidence,
            )
        )

        if context_decision is not None:

            return {
                "ok": True,
                "engine": "intent-fusion",
                "text": text,
                "intent": context_decision["intent"],
                "confidence": round(
                    context_decision[
                        "confidence"
                    ],
                    6,
                ),
                "decision": context_decision[
                    "decision"
                ],
                "reason": context_decision[
                    "reason"
                ],
                "rule": {
                    "intent": rule_intent,
                    "confidence": round(
                        rule_confidence,
                        6,
                    ),
                },
                "semantic": {
                    "intent": semantic_intent,
                    "confidence": round(
                        semantic_confidence,
                        6,
                    ),
                    "top_candidates": semantic.get(
                        "top_candidates",
                        [],
                    ),
                },
            }

        # ==================================================
        # NORMAL FUSION
        # ==================================================

        final_intent = rule_intent
        final_confidence = rule_confidence
        decision = "rule_default"

        # Rule + semantic sepakat
        if (
            rule_intent != "unknown"
            and rule_intent == semantic_intent
        ):

            final_intent = rule_intent

            final_confidence = (
                (rule_confidence * 0.60)
                + (semantic_confidence * 0.40)
            )

            decision = "agreement"

        # Rule tidak tahu -> semantic recovery
        elif (
            rule_intent == "unknown"
            and semantic_confidence
            >= self.SEMANTIC_MIN_THRESHOLD
        ):

            final_intent = semantic_intent
            final_confidence = semantic_confidence
            decision = "semantic_recovery"

        # Semantic cukup kuat mengalahkan rule
        elif (
            semantic_confidence
            >= self.SEMANTIC_MIN_THRESHOLD
            and (
                semantic_confidence
                - rule_confidence
            )
            >= self.SEMANTIC_MARGIN
        ):

            final_intent = semantic_intent
            final_confidence = semantic_confidence
            decision = "semantic_override"

        # Default rule
        else:

            final_intent = rule_intent
            final_confidence = rule_confidence
            decision = "rule_fallback"

        return {
            "ok": True,
            "engine": "intent-fusion",
            "text": text,
            "intent": final_intent,
            "confidence": round(
                float(final_confidence),
                6,
            ),
            "decision": decision,
            "rule": {
                "intent": rule_intent,
                "confidence": round(
                    rule_confidence,
                    6,
                ),
            },
            "semantic": {
                "intent": semantic_intent,
                "confidence": round(
                    semantic_confidence,
                    6,
                ),
                "top_candidates": semantic.get(
                    "top_candidates",
                    [],
                ),
            },
        }

    def health(self) -> dict[str, Any]:

        return {
            "ok": True,
            "engine": "intent-fusion",
            "rule": {
                "available": (
                    self.rule_classifier
                    is not None
                ),
            },
            "semantic": (
                self.semantic_engine.health()
            ),
        }

    def stop(self) -> None:

        self.semantic_engine.stop()

from __future__ import annotations

import json
import subprocess
import threading
from pathlib import Path
from typing import Any


class IndoBERTClient:
    """
    Bridge Nusantara Core -> IndoBERT Worker.

    IndoBERT berjalan pada virtual environment terpisah,
    sehingga Nusantara Core tidak membutuhkan torch/transformers.
    """

    def __init__(
        self,
        python_executable: str | None = None,
        worker_path: str | None = None,
    ) -> None:

        project_root = Path(__file__).resolve().parents[3]

        if python_executable is None:
            python_executable = str(
                project_root
                / "nusantara-models"
                / ".venv"
                / "Scripts"
                / "python.exe"
            )

        if worker_path is None:
            worker_path = str(
                project_root
                / "nusantara-models"
                / "indobert_worker.py"
            )

        self.python_executable = python_executable
        self.worker_path = worker_path

        self._process: subprocess.Popen[str] | None = None
        self._lock = threading.Lock()

    def start(self) -> None:
        """Menjalankan IndoBERT worker."""

        if self.is_running():
            return

        self._process = subprocess.Popen(
            [
                self.python_executable,
                self.worker_path,
            ],
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            text=True,
            encoding="utf-8",
            bufsize=1,
        )

    def is_running(self) -> bool:
        """Memeriksa apakah worker IndoBERT aktif."""

        return (
            self._process is not None
            and self._process.poll() is None
        )

    def encode(self, text: str) -> dict[str, Any]:
        """Mengirim teks ke IndoBERT dan menerima embedding."""

        if not isinstance(text, str):
            text = str(text)

        text = text.strip()

        if not text:
            return {
                "ok": False,
                "engine": "indobert-client",
                "error": "text wajib diisi",
            }

        with self._lock:

            self.start()

            if self._process is None:
                return {
                    "ok": False,
                    "engine": "indobert-client",
                    "error": "Worker IndoBERT gagal dimulai.",
                }

            if (
                self._process.stdin is None
                or self._process.stdout is None
            ):
                return {
                    "ok": False,
                    "engine": "indobert-client",
                    "error": "Pipe IndoBERT tidak tersedia.",
                }

            request = {
                "text": text,
            }

            try:
                self._process.stdin.write(
                    json.dumps(
                        request,
                        ensure_ascii=False,
                    )
                    + "\n"
                )

                self._process.stdin.flush()

                response_line = self._process.stdout.readline()

                if not response_line:
                    self._process = None

                    return {
                        "ok": False,
                        "engine": "indobert-client",
                        "error": (
                            "Worker IndoBERT "
                            "tidak memberikan response."
                        ),
                    }

                return json.loads(response_line)

            except BrokenPipeError:

                self._process = None

                return {
                    "ok": False,
                    "engine": "indobert-client",
                    "error": "Pipe IndoBERT terputus.",
                }

            except json.JSONDecodeError as exc:

                return {
                    "ok": False,
                    "engine": "indobert-client",
                    "error": (
                        f"Response JSON tidak valid: {exc}"
                    ),
                }

            except Exception as exc:

                return {
                    "ok": False,
                    "engine": "indobert-client",
                    "error": str(exc),
                }

    def health(self) -> dict[str, Any]:
        """Status koneksi ke IndoBERT worker."""

        running = self.is_running()

        return {
            "ok": running,
            "engine": "indobert-client",
            "worker_running": running,
            "python": self.python_executable,
            "worker": self.worker_path,
        }

    def stop(self) -> None:
        """Menghentikan worker IndoBERT."""

        process = self._process

        if process is None:
            return

        try:
            if process.stdin:
                process.stdin.close()
        except Exception:
            pass

        try:
            process.terminate()
            process.wait(timeout=5)
        except Exception:
            try:
                process.kill()
            except Exception:
                pass

        self._process = None

﻿from __future__ import annotations

from typing import Any
import math
import threading

from app.language.semantic.indobert_client import IndoBERTClient
from app.language.semantic.intent_prototypes import INTENT_PROTOTYPES


class SemanticIntentEngine:
    """
    Semantic Intent Engine Nusantara AI.

    Pipeline:

        text
          ↓
        IndoBERTClient
          ↓
        768D embedding
          ↓
        cosine similarity
          ↓
        intent prototypes
          ↓
        semantic intent

    IndoBERT bersifat persistent dan lazy-loaded.
    """

    VERSION = "1.3.1-indobert"

    MODEL = "indobenchmark/indobert-base-p1"
    EMBEDDING_DIMENSION = 768

    def __init__(
        self,
        client: IndoBERTClient | None = None,
    ) -> None:

        self.client = client or IndoBERTClient()

        self.prototype_embeddings: dict[
            str,
            list[list[float]],
        ] = {}

        self.ready = False
        self.building = False
        self.build_error: str | None = None

        self._lock = threading.RLock()

    # ==========================================================
    # COSINE SIMILARITY
    # ==========================================================

    @staticmethod
    def cosine_similarity(
        vector_a: list[float],
        vector_b: list[float],
    ) -> float:

        if not vector_a or not vector_b:
            return 0.0

        if len(vector_a) != len(vector_b):
            return 0.0

        dot_product = 0.0
        norm_a = 0.0
        norm_b = 0.0

        for a, b in zip(vector_a, vector_b):
            try:
                a = float(a)
                b = float(b)
            except (TypeError, ValueError):
                return 0.0

            dot_product += a * b
            norm_a += a * a
            norm_b += b * b

        denominator = math.sqrt(norm_a) * math.sqrt(norm_b)

        if denominator <= 0.0:
            return 0.0

        similarity = dot_product / denominator

        if not math.isfinite(similarity):
            return 0.0

        return max(-1.0, min(1.0, similarity))

    # ==========================================================
    # VALIDATE EMBEDDING
    # ==========================================================

    @classmethod
    def _validate_embedding(
        cls,
        embedding: Any,
    ) -> bool:

        if not isinstance(embedding, list):
            return False

        if len(embedding) != cls.EMBEDDING_DIMENSION:
            return False

        for value in embedding:
            if not isinstance(value, (int, float)):
                return False

            if not math.isfinite(float(value)):
                return False

        return True

    # ==========================================================
    # BUILD PROTOTYPE INDEX
    # ==========================================================

    def build_index(self, force: bool = False) -> None:

        with self._lock:

            if self.ready and not force:
                return

            if self.building:
                return

            self.building = True
            self.build_error = None

            try:

                new_index: dict[
                    str,
                    list[list[float]],
                ] = {}

                for intent_name, examples in INTENT_PROTOTYPES.items():

                    if not isinstance(examples, (list, tuple)):
                        continue

                    embeddings: list[list[float]] = []

                    for example in examples:

                        example = str(example).strip()

                        if not example:
                            continue

                        result = self.client.encode(example)

                        if not result.get("ok"):
                            raise RuntimeError(
                                "Gagal membuat embedding prototype "
                                f"'{intent_name}': "
                                f"{result.get('error', 'unknown error')}"
                            )

                        embedding = result.get("embedding")

                        if not self._validate_embedding(
                            embedding
                        ):
                            raise RuntimeError(
                                "Embedding prototype tidak valid "
                                f"untuk intent '{intent_name}'. "
                                f"Diharapkan {self.EMBEDDING_DIMENSION}D."
                            )

                        embeddings.append(
                            [float(x) for x in embedding]
                        )

                    if embeddings:
                        new_index[intent_name] = embeddings

                if not new_index:
                    raise RuntimeError(
                        "Tidak ada prototype embedding yang berhasil dibuat."
                    )

                self.prototype_embeddings = new_index
                self.ready = True

            except Exception as exc:

                self.ready = False
                self.prototype_embeddings.clear()
                self.build_error = str(exc)

                raise

            finally:
                self.building = False

    # ==========================================================
    # CLASSIFY
    # ==========================================================

    def classify(
        self,
        text: str,
        top_k: int = 3,
    ) -> dict[str, Any]:

        text = str(text).strip()

        if not text:
            return {
                "ok": False,
                "engine": "indobert-semantic",
                "version": self.VERSION,
                "error": "text wajib diisi",
            }

        if top_k < 1:
            top_k = 1

        # ------------------------------------------------------
        # Ensure prototype index
        # ------------------------------------------------------

        try:

            if not self.ready:
                self.build_index()

        except Exception as exc:

            return {
                "ok": False,
                "engine": "indobert-semantic",
                "version": self.VERSION,
                "model": self.MODEL,
                "error": (
                    "IndoBERT semantic index gagal dibangun: "
                    f"{exc}"
                ),
            }

        # ------------------------------------------------------
        # Encode user query
        # ------------------------------------------------------

        try:

            result = self.client.encode(text)

        except Exception as exc:

            return {
                "ok": False,
                "engine": "indobert-semantic",
                "version": self.VERSION,
                "model": self.MODEL,
                "error": (
                    "IndoBERT client exception: "
                    f"{exc}"
                ),
            }

        if not result.get("ok"):

            return {
                "ok": False,
                "engine": "indobert-semantic",
                "version": self.VERSION,
                "model": self.MODEL,
                "error": result.get(
                    "error",
                    "Gagal melakukan embedding.",
                ),
            }

        query_embedding = result.get("embedding")

        if not self._validate_embedding(query_embedding):

            return {
                "ok": False,
                "engine": "indobert-semantic",
                "version": self.VERSION,
                "model": self.MODEL,
                "error": (
                    "Embedding input tidak valid. "
                    f"Diharapkan {self.EMBEDDING_DIMENSION}D."
                ),
            }

        # ------------------------------------------------------
        # Similarity
        # ------------------------------------------------------

        candidates: list[dict[str, Any]] = []

        for intent_name, embeddings in (
            self.prototype_embeddings.items()
        ):

            if not embeddings:
                continue

            similarities = [
                self.cosine_similarity(
                    query_embedding,
                    embedding,
                )
                for embedding in embeddings
            ]

            if not similarities:
                continue

            best_similarity = max(similarities)

            average_similarity = (
                sum(similarities)
                / len(similarities)
            )

            candidates.append(
                {
                    "intent": intent_name,
                    "similarity": round(
                        best_similarity,
                        6,
                    ),
                    "average_similarity": round(
                        average_similarity,
                        6,
                    ),
                }
            )

        candidates.sort(
            key=lambda item: item["similarity"],
            reverse=True,
        )

        top_candidates = candidates[:top_k]

        if not top_candidates:

            return {
                "ok": False,
                "engine": "indobert-semantic",
                "version": self.VERSION,
                "model": self.MODEL,
                "error": "Tidak ada prototype intent.",
            }

        best = top_candidates[0]

        confidence = float(
            best.get("similarity", 0.0)
        )

        return {
            "ok": True,
            "engine": "indobert-semantic",
            "version": self.VERSION,
            "model": self.MODEL,
            "text": text,
            "intent": best["intent"],
            "confidence": round(
                confidence,
                6,
            ),
            "top_candidates": top_candidates,
            "prototype_count": len(
                self.prototype_embeddings
            ),
            "prototype_examples": sum(
                len(values)
                for values in self.prototype_embeddings.values()
            ),
        }

    # ==========================================================
    # HEALTH
    # ==========================================================

    def health(self) -> dict[str, Any]:

        try:
            worker = self.client.health()
        except Exception as exc:
            worker = {
                "ok": False,
                "error": str(exc),
            }

        return {
            "ok": bool(
                self.ready
                and worker.get("ok", False)
            ),
            "engine": "indobert-semantic",
            "version": self.VERSION,
            "model": self.MODEL,
            "ready": self.ready,
            "building": self.building,
            "intent_count": len(
                self.prototype_embeddings
            ),
            "prototype_examples": sum(
                len(values)
                for values in self.prototype_embeddings.values()
            ),
            "embedding_dimension": self.EMBEDDING_DIMENSION,
            "build_error": self.build_error,
            "worker": worker,
        }

    # ==========================================================
    # STOP
    # ==========================================================

    def stop(self) -> None:

        try:
            self.client.stop()
        except Exception:
            pass

        with self._lock:
            self.ready = False
            self.building = False


__all__ = [
    "SemanticIntentEngine",
]

"""
MCP Server - MCP protocol support.
"""
from __future__ import annotations

import uuid
from dataclasses import dataclass, field
from datetime import datetime
from typing import Any, Callable, Dict, List, Optional

from app.mcp.schemas import MCPTool, MCPServerInfo, MCPSessionInfo, MCPError


class MCPServer:
    """
    MCP Server sederhana.
    """

    def __init__(self, name: str = "nusantara-mcp", version: str = "0.1.0"):
        self.name = name
        self.version = version
        self._tools: Dict[str, MCPTool] = {}
        self._sessions: Dict[str, Dict[str, Any]] = {}

    def register_tool(self, tool: MCPTool = None, **kwargs) -> "MCPServer":
        """Daftarkan MCP tool; mendukung object maupun keyword contract."""
        if tool is None:
            tool = MCPTool(name=kwargs["name"], description=kwargs.get("description", ""), input_schema=kwargs.get("input_schema", {}), handler=kwargs["handler"], permissions=kwargs.get("permissions", []))
        self._tools[tool.name] = tool
        return self

    def get_session_info(self, session_id: str):
        session=self.get_session(session_id)
        if not session: return None
        return {"session_id": session_id, "active_tools": len(self._tools), "active": session.get("active", False)}

    def register(
        self,
        name: str,
        description: str,
        input_schema: Dict[str, Any],
        handler: Callable[[Dict[str, Any]], Dict[str, Any]],
        permissions: List[str] = None,
    ) -> "MCPServer":
        """Shortcut register tool."""
        tool = MCPTool(
            name=name,
            description=description,
            input_schema=input_schema,
            handler=handler,
            permissions=permissions or [],
        )
        return self.register_tool(tool)

    def list_tools(self) -> List[Dict[str, Any]]:
        """List semua tools."""
        return [
            {
                "name": tool.name,
                "description": tool.description,
                "input_schema": tool.input_schema,
                "permissions": tool.permissions,
            }
            for tool in self._tools.values()
        ]

    def get_tool(self, name: str) -> Optional[MCPTool]:
        """Dapatkan tool oleh nama."""
        return self._tools.get(name)

    def call_tool(self, name: str, arguments: Dict[str, Any]) -> Dict[str, Any]:
        """Call tool dengan nama dan arguments."""
        tool = self._tools.get(name)
        if tool is None:
            raise MCPError(f"Tool '{name}' tidak ditemukan")

        try:
            result = tool.handler(arguments)
            return result
        except Exception as e:
            raise MCPError(f"Error calling tool '{name}': {e}")

    def create_session(self, session_id: Optional[str] = None) -> str:
        """Buat sesi baru."""
        if session_id is None:
            session_id = uuid.uuid4().hex[:12]
        self._sessions[session_id] = {
            "session_id": session_id,
            "created_at": datetime.utcnow().isoformat(),
            "tools": list(self._tools.keys()),
            "active": True,
        }
        return session_id

    def get_session(self, session_id: str) -> Optional[Dict[str, Any]]:
        """Dapatkan informasi sesi."""
        session = self._sessions.get(session_id)
        if session and session.get("active"):
            return session
        return None

    def close_session(self, session_id: str) -> bool:
        """Tutup sesi."""
        if session_id in self._sessions:
            self._sessions[session_id]["active"] = False
            return True
        return False

    def get_info(self) -> MCPServerInfo:
        """Dapatkan informasi server."""
        return MCPServerInfo(
            name=self.name,
            version=self.version,
            tool_count=len(self._tools),
            session_count=sum(1 for s in self._sessions.values() if s.get("active")),
        )


class MCPSession:
    """
    Sesi MCP untuk berinteraksi dengan server.
    """

    def __init__(self, server: MCPServer, session_id: Optional[str] = None):
        self.server = server
        self.session_id = server.create_session(session_id)
        self._initialize_session()

    def _initialize_session(self):
        """Inisialisasi sesi."""
        pass

    def call(self, tool_name: str, arguments: Dict[str, Any]) -> Dict[str, Any]:
        """Call tool dalam sesi ini."""
        return self.server.call_tool(tool_name, arguments)

    def list_tools(self) -> List[Dict[str, Any]]:
        """List tools yang tersedia."""
        return self.server.list_tools()

    def get_info(self) -> MCPSessionInfo:
        """Dapatkan informasi sesi."""
        session = self.server.get_session(self.session_id)
        if session:
            return MCPSessionInfo(
                session_id=self.session_id,
                server_name=self.server.name,
                server_version=self.server.version,
                active_tools=session.get("tools", []),
                created_at=session.get("created_at"),
            )
        return MCPSessionInfo(
            session_id=self.session_id,
            server_name=self.server.name,
            server_version=self.server.version,
            active_tools=[],
            created_at=None,
        )


_default_server = MCPServer()


def create_server(name: str = "nusantara-mcp") -> MCPServer:
    """Buat MCP server baru."""
    return MCPServer(name=name)


def get_default_server() -> MCPServer:
    """Dapatkan default MCP server."""
    return _default_server

"""
MCP Session - Sesi untuk berinterasi dengan MCP server.
"""
from __future__ import annotations

from typing import Any, Dict, Optional

from app.mcp.mcp import MCPServer, MCPSession as _MCPSession
from app.mcp.schemas import MCPSessionInfo


class Session:
    """
    Wrapper session MCP untuk penggunaan yang lebih sederhana.
    """

    def __init__(
        self,
        server: MCPServer,
        session_id: Optional[str] = None,
    ):
        self._session = _MCPSession(server, session_id)
        self.session_id = self._session.session_id
        self.server = server

    def call(self, tool_name: str, arguments: Dict[str, Any]) -> Dict[str, Any]:
        """Call tool melalui session."""
        return self._session.call(tool_name, arguments)

    def list_tools(self) -> list:
        """List tools yang tersedia."""
        return self._session.list_tools()

    def get_info(self) -> MCPSessionInfo:
        """Dapatkan informasi session."""
        return self._session.get_info()

    def close(self) -> bool:
