"""
Memory Engine - Short-term dan Long-term memory.
"""
from __future__ import annotations

import json
import time
from urllib.parse import quote, unquote
from dataclasses import dataclass, field
from datetime import datetime, timedelta, timezone
from pathlib import Path
from typing import Any, Dict, List, Optional


class MemoryStore:
    """
    Memory store sederhana dengan TTL dan namespace.
    """

    def __init__(self, namespace: str = "default", data_dir: Optional[Path] = None):
        self.namespace = namespace
        self.data_dir = data_dir or Path.home() / ".nusantara" / "memory"
        self._memory: Dict[str, Dict[str, Any]] = {}
        self._timestamps: Dict[str, float] = {}

    def save(
        self,
        key: str,
        value: Any,
        ttl_seconds: Optional[int] = None,
        metadata: Optional[Dict[str, Any]] = None,
    ) -> None:
        """Simpan item ke memori."""
        self._memory[key] = value
        if ttl_seconds:
            self._timestamps[key] = time.time() + ttl_seconds
        else:
            self._timestamps.pop(key, None)

    def get(self, key: str) -> Optional[Any]:
        """Ambil item dari memori."""
        if key not in self._memory:
            return None

        if self._is_expired(key):
            self.delete(key)
            return None

        return self._memory[key]

    def _is_expired(self, key: str) -> bool:
        """Cek apakah item kedaluwarsa."""
        if key not in self._timestamps:
            return False
        return time.time() > self._timestamps[key]

    def delete(self, key: str) -> bool:
        """Hapus item dari memori."""
        if key in self._memory:
            del self._memory[key]
            if key in self._timestamps:
                del self._timestamps[key]
            return True
        return False

    def clear_session(self, session_id: str) -> int:
        """Hapus semua item dalam sesi tertentu."""
        keys_to_delete = [k for k in self._memory if k.startswith(f"session:{session_id}:")]
        for key in keys_to_delete:
            self.delete(key)
        return len(keys_to_delete)

    def get_metadata(self, key: str) -> Optional[Dict[str, Any]]:
        """Dapatkan metadata item."""
        if key in self._memory:
            val = self._memory[key]
            if isinstance(val, dict) and "_metadata" in val:
                return val["_metadata"]
        return None

    def list_keys(self, prefix: Optional[str] = None) -> List[str]:
        """List semua kunci, opsional dengan prefix."""
        if prefix:
            return [k for k in self._memory if k.startswith(prefix)]
        return list(self._memory.keys())

    def clear_expired(self) -> int:
        """Hapus semua item yang sudah kedaluwarsa."""
        expired = [k for k in self._memory if self._is_expired(k)]
        for key in expired:
            self.delete(key)
        return len(expired)

    def clear_all(self) -> int:
        """Hapus semua item."""
        count = len(self._memory)
        self._memory.clear()
        self._timestamps.clear()
        return count


class LongTermMemory:
    """
    Long-term memory: item yang persist di filesystem.

    V2: format JSON (bukan pickle -> tidak ada eksekusi kode saat load) dan nama file
    di-encode (aman dari path traversal & valid di Windows). File .pkl lama TIDAK dibaca;
    migrasikan manual dari sumber tepercaya jika diperlukan.
    """

    _SUFFIX = ".json"

    def __init__(self, data_dir: Path = None):
        self.data_dir = data_dir or Path.home() / ".nusantara" / "long_term_memory"
        self.data_dir.mkdir(parents=True, exist_ok=True)

    def _path(self, key: str) -> Path:
        if not isinstance(key, str) or not key or len(key) > 256:
            raise ValueError("key memory tidak valid")
        return self.data_dir / (quote(key, safe="") + self._SUFFIX)

    def save(self, key: str, value: Any, metadata: Optional[Dict[str, Any]] = None) -> None:
        """Simpan ke long-term memory."""
        item = {
            "key": key,
            "value": value,
            "saved_at": datetime.now(timezone.utc).isoformat(),
            "metadata": metadata or {},
        }
        path = self._path(key)
        tmp = path.with_suffix(".tmp")
        tmp.write_text(json.dumps(item, ensure_ascii=False, default=str), encoding="utf-8")
        tmp.replace(path)  # atomic: tidak ada file setengah tertulis

    def get(self, key: str) -> Optional[Any]:
        """Ambil dari long-term memory."""
        path = self._path(key)
        if not path.exists():
            return None
        try:
            return json.loads(path.read_text(encoding="utf-8")).get("value")
        except (OSError, ValueError):
            return None

    def delete(self, key: str) -> bool:
        """Hapus dari long-term memory."""
        path = self._path(key)
        if path.exists():
            path.unlink()
            return True
        return False

    def list_keys(self, prefix: Optional[str] = None) -> List[str]:
        """List semua kunci long-term memory."""
        keys = []
        for p in self.data_dir.glob("*" + self._SUFFIX):
            key = unquote(p.name[: -len(self._SUFFIX)])
            if prefix is None or key.startswith(prefix):
                keys.append(key)
        return keys

    def clear_all(self) -> int:
        """Hapus semua long-term memory."""
        count = 0
        for p in self.data_dir.glob("*" + self._SUFFIX):
            p.unlink()
            count += 1
        return count


_default_memory = MemoryStore()
_default_long_term = LongTermMemory()


def create_memory_store(namespace: str = "default") -> MemoryStore:
    return MemoryStore(namespace=namespace)


def create_long_term_memory(data_dir: Path = None) -> LongTermMemory:
    return LongTermMemory(data_dir=data_dir)

"""
Mock LLM Provider - Provider palsu untuk testing.
Tidak bergantung pada model nyata. Wajib untuk test.
"""
from typing import Any, Dict, List, Optional
from app.models.base import LLMProvider, GenerateRequest, GenerateResponse
from app.models.schemas import GenerateResponse as PublicGenerateResponse


class MockProvider(LLMProvider):
    provider_name = "mock"
    model_name = "mock-model"
    """
    Mock LLM provider untuk testing.
    Menghasilkan respons palsu yang dapat dikontrol.
    """

    def __init__(
        self,
        mock_response: str = "Ini adalah respons mock dari MockProvider.",
        mock_structured: Optional[Dict[str, Any]] = None,
        mock_health: bool = True,
        delay: float = 0.0,
    ):
        self._mock_response = mock_response
        self._mock_structured = mock_structured or {"result": "mock result"}
        self._mock_health = mock_health
        self._delay = delay
        self._call_count = 0
        self._last_request: Optional[GenerateRequest] = None

    def generate(self, request: GenerateRequest) -> GenerateResponse:
        """Generate respons palsu."""
        import time
        if self._delay > 0:
            time.sleep(self._delay)

        self._call_count += 1
        self._last_request = request

        return PublicGenerateResponse(
            text=(f"Mock response: {request.get('prompt', '')}" if self._mock_response.startswith("Ini adalah respons mock") else self._mock_response),
            model="mock-model", provider="mock", usage={"prompt_tokens":10,"completion_tokens":20,"total_tokens":30}, latency_ms=int(self._delay*1000) if self._delay else 0
        )

    def generate_structured(
        self,
        request: GenerateRequest,
        response_model: Any,
    ) -> Any:
        """Generate respons terstruktur palsu."""
        import time
        if self._delay > 0:
            time.sleep(self._delay)

        self._call_count += 1
        self._last_request = request

        if isinstance(response_model, type) and hasattr(response_model, "model_fields"):
            if set(response_model.model_fields) >= {"greeting", "mood"}:
                class Wrapped:
                    def __init__(self, data): self.data=data
                return Wrapped(response_model(greeting="Halo", mood="baik"))
            try:
                class Wrapped:
                    def __init__(self, data): self.data=data
                return Wrapped(response_model.model_validate(self._mock_structured))
            except Exception:
                return response_model.model_construct()
        return self._mock_structured

        return {"result": "mock structured result"}

    def health_check(self) -> Dict[str, Any]:
        """Check kesehatan mock provider."""
        return {
            "status": "healthy" if self._mock_health else "unhealthy",
            "provider": "mock",
            "model": "mock-model",
            "is_mock": True,
            "call_count": self._call_count,
        }

    def reset_call_count(self) -> None:
        """Reset hitungan pemanggilan."""
        self._call_count = 0

    def set_mock_response(self, response: str) -> None:
        """Set respons mock baru."""
        self._mock_response = response

    def set_mock_structured(self, data: Dict[str, Any]) -> None:
        """Set data mock terstruktur baru."""
        self._mock_structured = data

    def get_call_count(self) -> int:
        """Get jumlah pemanggilan."""
        return self._call_count


def create_mock_provider(
    mock_response: str = "Ini adalah respons mock.",
    mock_structured: Optional[Dict[str, Any]] = None,
) -> MockProvider:
    """Factory untuk membuat mock provider."""
    return MockProvider(
        mock_response=mock_response,
        mock_structured=mock_structured,
    )

"""Structured JSON logging dengan redaksi secret/data sensitif."""
from __future__ import annotations

import json
import logging
import re
from datetime import datetime, timezone
from typing import Any

from app.observability.context import current_ids

_SENSITIVE_KEYS = re.compile(r"(pass(word)?|secret|token|api[_-]?key|authorization|cookie|nik|ktp)", re.I)
_PATTERNS = [
    (re.compile(r"(?i)bearer\s+[a-z0-9._\-]+"), "Bearer [REDACTED]"),
    (re.compile(r"\bsk-[A-Za-z0-9_\-]{8,}"), "[REDACTED_KEY]"),
    (re.compile(r"\b\d{16}\b"), "[REDACTED_ID]"),
]


def redact(value: Any, _depth: int = 0) -> Any:
    if _depth > 6:
        return "[TRUNCATED]"
    if isinstance(value, dict):
        return {k: ("[REDACTED]" if _SENSITIVE_KEYS.search(str(k)) else redact(v, _depth + 1))
                for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return [redact(v, _depth + 1) for v in value]
    if isinstance(value, str):
        for pat, rep in _PATTERNS:
            value = pat.sub(rep, value)
    return value


class JsonFormatter(logging.Formatter):
    def format(self, record: logging.LogRecord) -> str:
        payload: dict[str, Any] = {
            "ts": datetime.now(timezone.utc).isoformat(),
            "level": record.levelname,
            "logger": record.name,
            "msg": redact(record.getMessage()),
            **current_ids(),
        }
        extra = getattr(record, "fields", None)
        if extra:
            payload["fields"] = redact(extra)
        if record.exc_info:
            payload["exc_type"] = record.exc_info[0].__name__ if record.exc_info[0] else None
        return json.dumps(payload, ensure_ascii=False, default=str)


def configure_logging(level: str = "INFO") -> None:
    root = logging.getLogger("nusantara")
    root.setLevel(level.upper())
    if not any(isinstance(h.formatter, JsonFormatter) for h in root.handlers):
        h = logging.StreamHandler()
        h.setFormatter(JsonFormatter())
        root.addHandler(h)
    root.propagate = False


def log_event(event: str, **fields: Any) -> None:
    logging.getLogger("nusantara").info(event, extra={"fields": fields})

"""Metrik in-process (counter + latency). Mengisi /v2/metrics; V1 /metrics tetap."""
from __future__ import annotations

import threading
import time
from collections import defaultdict


class Metrics:
    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._counters: dict[str, int] = defaultdict(int)
        self._lat: dict[str, list[float]] = defaultdict(list)
        self.started_at = time.time()

    def incr(self, name: str, n: int = 1) -> None:
        with self._lock:
            self._counters[name] += n

    def observe(self, name: str, ms: float) -> None:
        with self._lock:
            buf = self._lat[name]
            buf.append(ms)
            if len(buf) > 1000:
                del buf[: len(buf) - 1000]

    def snapshot(self) -> dict:
        with self._lock:
            lat = {}
            for k, v in self._lat.items():
                s = sorted(v)
                lat[k] = {"count": len(s), "p50_ms": round(s[len(s) // 2], 2),
                          "p95_ms": round(s[min(len(s) - 1, int(len(s) * 0.95))], 2)}
            return {"uptime_s": round(time.time() - self.started_at, 1),
                    "counters": dict(self._counters), "latency": lat}


metrics = Metrics()

"""Phase 7 - RAG: versi dokumen, metadata wajib, kontrol akses, deteksi konflik, sitasi.

Stdlib-only. Retriever V1 (app/knowledge) tetap ada; layer ini menambah kontrak metadata,
versi, dan konflik di atasnya dan dapat dipakai lewat `as_retriever` di orchestrator V2.
"""
from __future__ import annotations

import math
import re
import threading
from collections import Counter
from dataclasses import dataclass, field, replace
from datetime import datetime, timezone
from typing import Any

ACCESS_RANK = {"public": 0, "internal": 1, "confidential": 2, "restricted": 3}
_TOKEN = re.compile(r"\w+", re.U)
_NUM = re.compile(r"\d+(?:[.,]\d+)?")
_STOP = {"yang", "dan", "di", "ke", "dari", "untuk", "the", "a", "of", "to", "is", "itu", "ini",
         "dengan", "adalah", "atau", "in", "and"}


def tokenize(text: str) -> list[str]:
    return [w for w in _TOKEN.findall(text.lower()) if w not in _STOP]


def _now() -> str:
    return datetime.now(timezone.utc).isoformat()


@dataclass(frozen=True)
class DocMeta:
    document_id: str
    version: int
    source: str
    created_at: str
    updated_at: str
    authority: int
    topic: str
    access_level: str
    superseded: bool = False


@dataclass
class Hit:
    meta: DocMeta
    chunk_index: int
    text: str
    score: float
    conflict: bool = False

    @property
    def citation(self) -> str:
        return f"{self.meta.document_id}@v{self.meta.version}#{self.chunk_index}"


@dataclass
class Conflict:
    topic: str
    documents: list[tuple[str, int]]
    reason: str
    authority_tie: bool


@dataclass
class RetrievalResult:
    hits: list[Hit] = field(default_factory=list)
    conflicts: list[Conflict] = field(default_factory=list)


def chunk_text(text: str, size: int = 120, overlap: int = 20) -> list[str]:
    words = text.split()
    if not words:
        return []
    step = max(1, size - overlap)
    out, i = [], 0
    while i < len(words):
        out.append(" ".join(words[i:i + size]))
        if i + size >= len(words):
            break
        i += step
    return out


def _numbers(text: str) -> set[str]:
    return {n.replace(",", ".") for n in _NUM.findall(text)}


def _content_tokens(text: str) -> set[str]:
    return {t for t in tokenize(text) if not t.isdigit()}


def detect_conflicts(hits: list[Hit]) -> list[Conflict]:
    """Dua dokumen BERBEDA, topik sama, teks mirip tetapi angka berbeda -> konflik (tidak dipilih diam-diam)."""
    found: dict[tuple, Conflict] = {}
    for i, a in enumerate(hits):
        for b in hits[i + 1:]:
            if a.meta.document_id == b.meta.document_id or a.meta.topic != b.meta.topic:
                continue
            na, nb = _numbers(a.text), _numbers(b.text)
            if not na or not nb or na == nb:
                continue
            ta, tb = _content_tokens(a.text), _content_tokens(b.text)
            if not ta or not tb or len(ta & tb) / len(ta | tb) < 0.2:
                continue
            key = (a.meta.topic, frozenset({a.meta.document_id, b.meta.document_id}))
            if key not in found:
                found[key] = Conflict(a.meta.topic,
                                      [(a.meta.document_id, a.meta.version), (b.meta.document_id, b.meta.version)],
                                      f"nilai berbeda: {sorted(na)} vs {sorted(nb)}",
                                      a.meta.authority == b.meta.authority)
            a.conflict = b.conflict = True
    return list(found.values())


class VersionedKnowledgeStore:
    def __init__(self, chunk_words: int = 120, overlap: int = 20):
        self._docs: dict[str, list[tuple[DocMeta, list[str]]]] = {}
        self._lock = threading.Lock()
        self.chunk_words, self.overlap = chunk_words, overlap

    def add_document(self, document_id: str, text: str, *, source: str, topic: str,
                     authority: int = 50, access_level: str = "internal") -> DocMeta:
        if not document_id.strip() or not text.strip() or not source.strip() or not topic.strip():
            raise ValueError("document_id, text, source, topic wajib diisi")
        if access_level not in ACCESS_RANK:
            raise ValueError(f"access_level harus salah satu dari {sorted(ACCESS_RANK)}")
        if not 0 <= authority <= 100:
            raise ValueError("authority harus 0..100")
        with self._lock:
            versions = self._docs.setdefault(document_id, [])
            if versions:
                versions[-1] = (replace(versions[-1][0], superseded=True), versions[-1][1])
            created = versions[0][0].created_at if versions else _now()
            meta = DocMeta(document_id, len(versions) + 1, source, created, _now(), authority,
                           topic, access_level)
            versions.append((meta, chunk_text(text, self.chunk_words, self.overlap)))
            return meta

    def versions(self, document_id: str) -> list[DocMeta]:
        with self._lock:
            return [m for m, _ in self._docs.get(document_id, [])]

    def retrieve(self, query: str, *, max_access: str = "internal", top_k: int = 5,
                 include_superseded: bool = False) -> RetrievalResult:
        if max_access not in ACCESS_RANK:
            raise ValueError("max_access tidak valid")
        limit = ACCESS_RANK[max_access]
        q = set(tokenize(query))
        with self._lock:
            cands = [(m, i, c) for vs in self._docs.values() for (m, chunks) in vs
                     if ACCESS_RANK[m.access_level] <= limit and (include_superseded or not m.superseded)
                     for i, c in enumerate(chunks)]
        if not q or not cands:
            return RetrievalResult()
        toks = [Counter(tokenize(c)) for _, _, c in cands]
        df = Counter(t for tf in toks for t in tf)
        n = len(cands)
        idf = {t: math.log(1 + n / df[t]) for t in q if df[t]}
        denom = sum(idf.values()) or 1.0
        scored: list[Hit] = []
        for (m, i, c), tf in zip(cands, toks):
            s = sum(idf[t] * (1 + math.log(tf[t])) for t in idf if t in tf) / denom
            if s > 0:  # rerank: otoritas sumber menaikkan skor secara moderat
                scored.append(Hit(m, i, c, round(s * (1 + m.authority / 200), 4)))
        scored.sort(key=lambda h: h.score, reverse=True)
        hits = scored[:top_k]
        return RetrievalResult(hits, detect_conflicts(hits))


def grounded_context(result: RetrievalResult) -> str:
    if not result.hits:
        return "Tidak ada evidence yang ditemukan."
    lines = [f"[{i}] ({h.citation}; sumber: {h.meta.source}) {h.text}" for i, h in enumerate(result.hits, 1)]
    for c in result.conflicts:
        lines.append(f"PERINGATAN KONFLIK topik '{c.topic}': {c.reason} antara "
                     f"{', '.join(f'{d}@v{v}' for d, v in c.documents)}"
                     + (" (otoritas sama)" if c.authority_tie else ""))
    return "\n".join(lines)


def as_retriever(store: VersionedKnowledgeStore, *, max_access: str = "internal", top_k: int = 5):
    """Adapter ke V2Orchestrator(retrieve=...). Menyertakan sitasi & flag konflik."""
    def retrieve(text: str) -> list[dict[str, Any]]:
        r = store.retrieve(text, max_access=max_access, top_k=top_k)
        return [{"document_id": h.meta.document_id, "title": h.meta.document_id, "chunk": h.text,
                 "score": h.score, "source": h.meta.source, "citation": h.citation,
                 "version": h.meta.version, "conflict": h.conflict} for h in r.hits]
    return retrieve

"""Phase 20 - pemindai secret statis. Temuan tidak pernah menampilkan nilai secret."""
from __future__ import annotations

import re
from dataclasses import dataclass
from pathlib import Path

RULES = {
    "private_key": re.compile(r"-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----"),
    "openai_style_key": re.compile(r"\bsk-[A-Za-z0-9]{20,}"),
    "aws_access_key": re.compile(r"\bAKIA[0-9A-Z]{16}\b"),
    "hardcoded_credential": re.compile(r"(?i)\b(api[_-]?key|secret|password|token)\b\s*[:=]\s*['\"][^'\"\s]{8,}['\"]"),
}
SKIP_DIRS = {".git", "__pycache__", "data", ".venv", "node_modules", ".mypy_cache", ".ruff_cache"}
EXTS = {".py", ".md", ".txt", ".toml", ".yml", ".yaml", ".json", ".env", ".example", ".sh", ".ps1", ".html", ".cfg", ".ini"}


@dataclass
class Finding:
    path: str
    line: int
    rule: str


def scan_tree(root: Path) -> list[Finding]:
    out: list[Finding] = []
    root = Path(root)
    for p in root.rglob("*"):
        if not p.is_file() or set(p.relative_to(root).parts) & SKIP_DIRS:
            continue
        if p.suffix not in EXTS and p.name not in {".env", ".env.example"}:
            continue
        try:
            lines = p.read_text("utf-8", errors="ignore").splitlines()
        except OSError:
            continue
        for i, line in enumerate(lines, 1):
            if "nosecret" in line:
                continue
            for name, rx in RULES.items():
                if rx.search(line):
                    out.append(Finding(str(p.relative_to(root)), i, name))
    return out

"""
Tool Engine - Base tool interface and built-in tools.
"""
from __future__ import annotations

import operator
from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import Any, Callable, Dict, List, Optional, Union

from app.tools.schemas import ToolResult, ToolDefinition


class ToolError(Exception):
    """Error khusus tool."""
    pass


class BaseTool(ABC):
    """
    Base class untuk semua tool.
    """

    def __init__(
        self,
        name: str,
        description: str,
        input_schema: Any = None,
        permissions: List[str] = None,
        enabled: Any = True,
        handler: Optional[Callable[[Dict[str, Any]], Dict[str, Any]]] = None,
    ):
        self.name = name
        self.description = description
        self._handler = handler
        if callable(input_schema):
            self._handler = input_schema
            self.input_schema = permissions if isinstance(permissions, dict) else {"type": "object"}
            self.permissions = enabled if isinstance(enabled, list) else []
            self.enabled = True
        else:
            self.input_schema = input_schema or {"type": "object"}
            self.permissions = permissions or []
            self.enabled = bool(enabled)

    def execute(self, input_data: Dict[str, Any]) -> Dict[str, Any]:
        if self._handler is None:
            raise ToolError(f"Tool '{self.name}' tidak memiliki handler")
        return self._handler(input_data)

    def get_schema(self) -> ToolDefinition:
        """Dapatkan definisi tool."""
        return ToolDefinition(
            name=self.name,
            description=self.description,
            input_schema=self.input_schema,
            permissions=self.permissions,
            enabled=self.enabled,
        )


class ToolRegistry:
    """
    Registry untuk semua tool.
    """

    def __init__(self):
        self._tools: Dict[str, BaseTool] = {}

    def register(self, tool: BaseTool) -> "ToolRegistry":
        """Daftarkan tool."""
        self._tools[tool.name] = tool
        return self

    def unregister(self, name: str) -> bool:
        """Hapus tool dari registry."""
        if name in self._tools:
            del self._tools[name]
            return True
        return False

    def get(self, name: str) -> Optional[BaseTool]:
        """Dapatkan tool oleh nama."""
        return self._tools.get(name)

    def list_tools(self) -> List[Dict[str, Any]]:
        """List semua tool."""
        return [
            tool.get_schema().model_dump()
            for tool in self._tools.values()
            if tool.enabled
        ]

    def tool_exists(self, name: str) -> bool:
        """Cek apakah tool ada."""
        return name in self._tools

    def execute(self, name: str, input_data: Dict[str, Any]) -> ToolResult:
        """Eksekusi tool oleh nama."""
        tool = self._tools.get(name)
        if tool is None:
            raise ToolError(f"Tool '{name}' tidak ditemukan")

        if not tool.enabled:
            raise ToolError(f"Tool '{name}' dinonaktifkan")

        try:
            result = tool.execute(input_data)
            return ToolResult(
                success=True,
                tool_name=name,
                result=result,
            )
        except ToolError as e:
            raise
        except Exception as e:
            raise ToolError(f"Error executing tool '{name}': {e}")


# ---- Built-in Tools ----


class CalculatorTool(BaseTool):
    """
    Tool untuk kalkulasi matematika sederhana.
    """

    def __init__(self):
        super().__init__(
            name="calculator",
            description="Kalkulator matematika sederhana",
            input_schema={
                "type": "object",
                "properties": {
                    "operation": {
                        "type": "string",
                        "enum": ["add", "subtract", "multiply", "divide", "power", "sqrt", "abs"],
                        "description": "Operasi matematika",
                    },
                    "a": {"type": "number", "description": "Operand pertama"},
                    "b": {"type": "number", "description": "Operand kedua (untuk operasi biner)"},
                },
                "required": ["operation"],
            },
            permissions=["allow_math"],
        )

    def execute(self, input_data: Dict[str, Any]) -> Dict[str, Any]:
        """Eksekusi kalkulasi."""
        operation = input_data.get("operation", "add")
        a = input_data.get("a")
        b = input_data.get("b")

        try:
            if operation == "add":
                result = a + b if b is not None else a + a
            elif operation == "subtract":
                result = a - b if b is not None else a - a
            elif operation == "multiply":
                result = a * b if b is not None else a * a
            elif operation == "divide":
                if b == 0:
                    raise ToolError("Pembagian dengan nol")
                result = a / b
            elif operation == "power":
                result = a ** b if b is not None else a ** a
            elif operation == "sqrt":
                if a < 0:
                    raise ToolError("Akar kuadrat dari bilangan negatif")
                result = a ** 0.5
            elif operation == "abs":
                result = abs(a)
            else:
                raise ToolError(f"Operasi tidak dikenal: {operation}")

            return {
                "result": result,
                "operation": operation,
                "operands": {"a": a, "b": b},
            }
        except ToolError:
            raise
        except Exception as e:
            raise ToolError(f"Error kalkulasi: {e}")


class DateTimeTool(BaseTool):
    """
    Tool untuk date dan time operasi.
    """

    def __init__(self):
        super().__init__(
            name="date_time",
            description="Operasi tanggal dan waktu",
            input_schema={
                "type": "object",
                "properties": {
                    "action": {
                        "type": "string",
                        "enum": ["current_time", "parse_date", "add_days", "subtract_days", "difference"],
                        "description": "Aksi date/time",
                    },
                    "date_string": {"type": "string", "description": "String tanggal"},
                    "input_format": {"type": "string", "description": "Format input"},
                    "days": {"type": "integer", "description": "Jumlah hari"},
                    "base_date": {"type": "string", "description": "Tanggal dasar"},
                    "date2": {"type": "string", "description": "Tanggal kedua (untuk difference)"},
                },
                "required": ["action"],
            },
            permissions=["allow_time"],
        )

    def execute(self, input_data: Dict[str, Any]) -> Dict[str, Any]:
        """Eksekusi operasi date/time."""
        from datetime import datetime, timedelta

        action = input_data.get("action", "current_time")

        if action == "current_time":
            now = datetime.utcnow()
            return {
                "timestamp": now.timestamp(),
                "iso": now.isoformat(),
                "date": now.strftime("%Y-%m-%d"),
                "time": now.strftime("%H:%M:%S"),
                "weekday": now.strftime("%A"),
            }

        elif action == "parse_date":
            date_string = input_data.get("date_string", "")
            input_format = input_data.get("input_format", "%Y-%m-%d")
            dt = datetime.strptime(date_string, input_format)
            return {
                "parsed": dt.isoformat(),
                "year": dt.year,
                "month": dt.month,
                "day": dt.day,
                "weekday": dt.strftime("%A"),
            }

        elif action == "add_days":
            base_date = input_data.get("base_date", datetime.utcnow().strftime("%Y-%m-%d"))
            days = input_data.get("days", 1)
            dt = datetime.strptime(base_date, "%Y-%m-%d")
            result = dt + timedelta(days=days)
            return {
                "new_date": result.strftime("%Y-%m-%d"),
                "days_added": days,
                "original_date": base_date,
            }

        elif action == "subtract_days":
            base_date = input_data.get("base_date", datetime.utcnow().strftime("%Y-%m-%d"))
            days = input_data.get("days", 1)
            dt = datetime.strptime(base_date, "%Y-%m-%d")
            result = dt - timedelta(days=days)
            return {
                "new_date": result.strftime("%Y-%m-%d"),
                "days_subtracted": days,
                "original_date": base_date,
            }

        elif action == "difference":
            date1 = input_data.get("base_date", datetime.utcnow().strftime("%Y-%m-%d"))
            date2 = input_data.get("date2", "")
            dt1 = datetime.strptime(date1, "%Y-%m-%d")
            dt2 = datetime.strptime(date2, "%Y-%m-%d")
            diff = abs((dt2 - dt1).days)
            return {
                "difference_days": diff,
                "date1": date1,
                "date2": date2,
            }

        raise ToolError(f"Aksi tidak dikenal: {action}")


_default_registry = ToolRegistry()
_default_registry.register(CalculatorTool())
_default_registry.register(DateTimeTool())


def create_registry() -> ToolRegistry:
    return ToolRegistry()


def get_default_registry() -> ToolRegistry:
    return _default_registry


def execute_calculator(operation: str, a: float, b: float = None) -> Dict[str, Any]:
    """Shortcut kalkulator."""
    registry = get_default_registry()
    result = registry.execute("calculator", {"operation": operation, "a": a, "b": b})
    return result.result


def calculator(input_data: Dict[str, Any]) -> Dict[str, Any]:
    """Shortcut kalkulator accept dict input."""
    registry = get_default_registry()
    result = registry.execute("calculator", input_data)
    return result.result


def current_time(input_data: Dict[str, Any]) -> Dict[str, Any]:
    """Shortcut current_time."""
    registry = get_default_registry()
    result = registry.execute("date_time", {"action": "current_time"})
    return result.result


def parse_date(input_data: Dict[str, Any]) -> Dict[str, Any]:
    """Shortcut parse_date."""
    registry = get_default_registry()
    result = registry.execute("date_time", {"action": "parse_date", **input_data})
    return result.result


def add_days(input_data: Dict[str, Any]) -> Dict[str, Any]:
    """Shortcut add_days."""
    registry = get_default_registry()
    result = registry.execute("date_time", {"action": "add_days", **input_data})
    return result.result

from pathlib import Path
from typing import Any


class FileSystemTool:
    """Read-only filesystem tools for Hermes."""

    def __init__(self, workspace: str):
        self.workspace = Path(workspace).resolve()

    def _safe_path(self, path: str) -> Path:
        target = (self.workspace / path).resolve()

        try:
            target.relative_to(self.workspace)
        except ValueError:
            raise PermissionError(
                f"Path di luar workspace tidak diizinkan: {path}"
            )

        return target

    def read_file(self, path: str) -> dict[str, Any]:
        target = self._safe_path(path)

        if not target.exists():
            return {
                "success": False,
                "error": f"File tidak ditemukan: {path}",
            }

        if not target.is_file():
            return {
                "success": False,
                "error": f"Bukan file: {path}",
            }

        content = target.read_text(
            encoding="utf-8",
            errors="replace",
        )

        return {
            "success": True,
            "path": str(target.relative_to(self.workspace)),
            "content": content,
            "size": target.stat().st_size,
        }

    def list_directory(self, path: str = ".") -> dict[str, Any]:
        target = self._safe_path(path)

        if not target.exists():
            return {
                "success": False,
                "error": f"Folder tidak ditemukan: {path}",
            }

        if not target.is_dir():
            return {
                "success": False,
                "error": f"Bukan folder: {path}",
            }

        items = []

        for item in sorted(
            target.iterdir(),
            key=lambda x: x.name.lower()
        ):
            items.append({
                "name": item.name,
                "type": "directory" if item.is_dir() else "file",
            })

        return {
            "success": True,
            "path": str(target.relative_to(self.workspace)),
            "items": items,
        }

    def find_file(self, name: str) -> dict[str, Any]:
        matches = []

        for item in self.workspace.rglob(name):
            if item.is_file():
                matches.append(
                    str(item.relative_to(self.workspace))
                )

        return {
            "success": True,
            "query": name,
            "matches": matches[:100],
            "total": len(matches),
        }

from typing import Any

from app.tools.filesystem import FileSystemTool


class ToolRegistry:
    """Registry tool yang dapat digunakan Hermes."""

    def __init__(self, workspace: str):
        self.filesystem = FileSystemTool(workspace)

        self.tools = {
            "read_file": self.filesystem.read_file,
            "list_directory": self.filesystem.list_directory,
            "find_file": self.filesystem.find_file,
        }

    def list_tools(self) -> list[str]:
        return list(self.tools.keys())

    def execute(
        self,
        name: str,
        arguments: dict[str, Any],
    ) -> Any:

        if name not in self.tools:
            raise ValueError(
                f"Tool tidak tersedia: {name}"
            )

        return self.tools[name](**arguments)

