_GRAPH_CACHE: Optional[dict[str, Any]] = None


def load_graph() -> dict[str, Any]:
    global _GRAPH_CACHE

    if _GRAPH_CACHE is not None:
        return _GRAPH_CACHE

    if not GRAPH_FILE.exists():
        return {
            "nodes": [],
            "edges": [],
        }

    try:
        data = json.loads(
            GRAPH_FILE.read_text(
                encoding="utf-8-sig"
            )
        )

        if not isinstance(data, dict):
            data = {}

        nodes = data.get("nodes", [])
        edges = data.get("edges", [])

        if not isinstance(nodes, list):
            nodes = []

        if not isinstance(edges, list):
            edges = []

        _GRAPH_CACHE = {
            "nodes": nodes,
            "edges": edges,
        }

        return _GRAPH_CACHE

    except Exception as exc:
        print(
            "[Graph] load failed:",
            exc,
        )

        return {
            "nodes": [],
            "edges": [],
        }


def search_graph(
    query: str,
    limit: int = 12,
) -> list[dict[str, Any]]:

    graph = load_graph()

    nodes = graph["nodes"]
    edges = graph["edges"]

    tokens = set(
        re.findall(
            r"[a-zA-Z0-9_]+",
            query.lower(),
        )
    )

    if not tokens:
        return []

    node_scores: dict[str, int] = {}

    for node in nodes:
        text = " ".join(
            str(node.get(key, ""))
            for key in (
                "id",
                "label",
                "source_file",
                "source_location",
                "file_type",
            )
        ).lower()

        score = sum(
            1
            for token in tokens
            if token in text
        )

        if score > 0:
            node_scores[
                str(node.get("id", ""))
            ] = score

    ranked_nodes = sorted(
        (
            (node_id, score)
            for node_id, score in node_scores.items()
        ),
        key=lambda x: x[1],
        reverse=True,
    )

    results: list[dict[str, Any]] = []

    node_map = {
        str(node.get("id", "")): node
        for node in nodes
    }

    for node_id, score in ranked_nodes[:limit]:
        node = node_map.get(node_id, {})

        results.append(
            {
                "type": "node",
                "id": node_id,
                "label": node.get(
                    "label",
                    node_id,
                ),
                "source_file": node.get(
                    "source_file",
                    "",
                ),
                "source_location": node.get(
                    "source_location",
                    "",
                ),
                "score": score,
            }
        )

    selected_ids = set(
        node_id
        for node_id, _ in ranked_nodes[:limit]
    )

    relationship_count = 0

    for edge in edges:

        source = str(
            edge.get("source", "")
        )

        target = str(
            edge.get("target", "")
        )

        if (
            source not in selected_ids
            and target not in selected_ids
        ):
            continue

        results.append(
            {
                "type": "relationship",
                "source": source,
                "target": target,
                "relation": edge.get(
                    "relation",
                    "",
                ),
                "context": edge.get(
                    "context",
                    "",
                ),
                "source_file": edge.get(
                    "source_file",
                    "",
                ),
                "source_location": edge.get(
                    "source_location",
                    "",
                ),
                "confidence": edge.get(
                    "confidence",
                    "",
                ),
            }
        )

        relationship_count += 1

        if relationship_count >= 30:
            break

    return results


