EXCLUDED_DIRS = {
    "__pycache__",
    ".git",
    ".venv",
    "backup",
    "backups",
    "research",
    "archive",
    "archives",
    "quarantine",
    "benchmark",
    "node_modules",
    "graphify-out",
    "dist",
    "build",
}

EXCLUDED_NAME_PARTS = {
    ".bak",
    ".backup",
    "backup_",
    "_backup",
    "before_",
    "_before_",
    "after_",
    "_after_",
    "patch_",
    "_patch",
}

SOURCE_EXTENSIONS = {
    ".py",
    ".md",
    ".json",
    ".yaml",
    ".yml",
    ".toml",
}


def collect_source_files() -> list[Path]:

    files: list[Path] = []

    for path in ROOT.rglob("*"):

        if not path.is_file():
            continue

        if path.suffix.lower() not in SOURCE_EXTENSIONS:
            continue

        relative_parts = {
            part.lower()
            for part in path.relative_to(ROOT).parts
        }

        if relative_parts.intersection(
            EXCLUDED_DIRS
        ):
            continue

        name = path.name.lower()

        if any(
            token in name
            for token in EXCLUDED_NAME_PARTS
        ):
            continue

        files.append(path)

    return files


def search_source(
    query: str,
    limit: int = 8,
) -> list[dict[str, Any]]:

    tokens = set(
        re.findall(
            r"[a-zA-Z0-9_]+",
            query.lower(),
        )
    )

    if not tokens:
        return []

    scored: list[tuple[int, Path]] = []

    for path in collect_source_files():

        try:
            text = path.read_text(
                encoding="utf-8",
                errors="ignore",
            )
        except Exception:
            continue

        low = text.lower()

        score = sum(
            1
            for token in tokens
            if token in low
        )

        if score > 0:
            scored.append(
                (
                    score,
                    path,
                )
            )

    scored.sort(
        key=lambda item: item[0],
        reverse=True,
    )

    results: list[dict[str, Any]] = []

    for score, path in scored[:limit]:

        try:
            text = path.read_text(
                encoding="utf-8",
                errors="ignore",
            )
        except Exception:
            continue

        # Jangan kirim source file terlalu besar ke model.
        if len(text) > 5000:
            text = text[:5000] + "\n...[TRUNCATED]"

        results.append(
            {
                "type": "source",
                "path": str(
                    path.relative_to(ROOT)
                ),
                "score": score,
                "content": text,
            }
        )

    return results


# ============================================================
# PRODUCTION KNOWLEDGE RAG
# ============================================================

AUTHORITY_LEVELS = {
    "official": 4,
    "verified": 3,
    "pending": 2,
    "unknown": 1,
    "expired": 0,
    "test": 0,
}


def normalize_authority(
    value: Any,
    text: str = "",
) -> str:

    raw = str(
        value or ""
    ).strip().lower()

    if raw in AUTHORITY_LEVELS:
        return raw

    combined = (
        raw
        + " "
        + text.lower()
    )

    # Fixture/test data harus selalu diperlakukan
    # sebagai non-authoritative.
    if (
        "test fixture" in combined
        or "data pengujian" in combined
        or "bukan sumber resmi" in combined
        or "test-" in combined
    ):
        return "test"

    return "unknown"


def object_to_dict(
    value: Any,
) -> Any:

    if value is None:
        return None

    if isinstance(value, dict):
        return value

    if hasattr(value, "model_dump"):
        try:
            return value.model_dump()
        except Exception:
            pass

    if hasattr(value, "dict"):
        try:
            return value.dict()
        except Exception:
            pass

    if hasattr(value, "__dict__"):
        try:
            return dict(
                value.__dict__
            )
        except Exception:
            pass

    return value


def normalize_production_pack(
    pack: Any,
) -> list[dict[str, Any]]:

    pack = object_to_dict(pack)

    if pack is None:
        return []

    if isinstance(pack, str):

        try:
            parsed = json.loads(pack)
            return normalize_production_pack(
                parsed
            )
        except Exception:
            return []

    if isinstance(pack, list):
        raw_items = pack

    elif isinstance(pack, dict):

        raw_items = None

        for key in (
            "evidence",
            "results",
            "items",
            "documents",
            "chunks",
        ):
            if isinstance(
                pack.get(key),
                list,
            ):
                raw_items = pack[key]
                break

        if raw_items is None:
            raw_items = []

    else:
        raw_items = []

    output: list[dict[str, Any]] = []

    for item in raw_items:

        item = object_to_dict(item)

        if not isinstance(item, dict):
            continue

        text = str(
            item.get("text")
            or item.get("chunk")
            or item.get("content")
            or ""
        ).strip()

        authority = normalize_authority(
            item.get("source_status")
            or item.get("authority")
            or item.get("status"),
            text,
        )

        normalized = {
            "chunk_id": item.get(
                "chunk_id"
            ),
            "document_id": item.get(
                "document_id"
            ),
            "title": item.get(
                "title"
            ),
            "service": item.get(
                "service"
            ),
            "content_type": item.get(
                "content_type"
            ),
            "text": text,
            "score": item.get(
                "score",
                0,
            ),
            "semantic_score": item.get(
                "semantic_score"
            ),
            "lexical_score": item.get(
                "lexical_score"
            ),
            "source_status": authority,
            "authority": authority,
            "source": item.get(
                "source"
            ),
            "url": item.get(
                "url"
            ),
        }

        output.append(normalized)

    return output


def search_production_knowledge(
    query: str,
    top_k: int = 5,
) -> list[dict[str, Any]]:

    rag = get_production_rag()

    if rag is None:
        return []

    try:
        pack = rag.retrieve(
            query=query,
            top_k=top_k,
        )

        return normalize_production_pack(
            pack
        )

    except Exception as exc:

        print(
            "[Production RAG] retrieval failed:",
            exc,
        )

        return []


# ============================================================
# AUTHORITY ENGINE
# ============================================================

def split_authority(
    evidence: list[dict[str, Any]],
) -> dict[str, list[dict[str, Any]]]:

    official = []
    verified = []
    non_authoritative = []

    for item in evidence:

        authority = normalize_authority(
            item.get("authority"),
            item.get("text", ""),
        )

        item["authority"] = authority
        item["source_status"] = authority

        if authority == "official":
            official.append(item)

        elif authority == "verified":
            verified.append(item)

        else:
            non_authoritative.append(item)

    return {
        "official": official,
        "verified": verified,
        "non_authoritative": non_authoritative,
    }


def authority_summary(
    groups: dict[str, list[dict[str, Any]]],
) -> dict[str, Any]:

    official = groups["official"]
    verified = groups["verified"]
    non_authoritative = groups[
        "non_authoritative"
    ]

    if official:
        level = "OFFICIAL"

    elif verified:
        level = "VERIFIED"

    elif non_authoritative:
        level = "NON_AUTHORITATIVE"

    else:
        level = "NO_EVIDENCE"

    return {
        "level": level,
        "official_count": len(official),
        "verified_count": len(verified),
        "non_authoritative_count": len(
            non_authoritative
        ),
        "grounding_allowed": bool(
            official or verified
        ),
    }


# ============================================================
# EVIDENCE BUILDER
# ============================================================

def build_grounding_context(
    query: str,
    graph: list[dict[str, Any]],
    source: list[dict[str, Any]],
    production: list[dict[str, Any]],
) -> tuple[str, dict[str, Any]]:

    groups = split_authority(
        production
    )

    summary = authority_summary(
        groups
    )

    lines: list[str] = []

    lines.append(
        "=== NUSANTARA DEVELOPER CORE EVIDENCE ==="
    )

    lines.append(
        f"QUERY: {query}"
    )

    lines.append("")

    lines.append(
        "=== GRAPH RAG ==="
    )

    for item in graph:

        if item.get("type") == "node":

            lines.append(
                "- NODE: "
                + str(
                    item.get("label", "")
                )
                + " | file="
                + str(
                    item.get("source_file", "")
                )
                + " | score="
                + str(
                    item.get("score", "")
                )
            )

        elif item.get(
            "type"
        ) == "relationship":

            lines.append(
                "- RELATION: "
                + str(
                    item.get("source", "")
                )
                + " --"
                + str(
                    item.get("relation", "")
                )
                + "--> "
                + str(
                    item.get("target", "")
                )
            )

    lines.append("")

    lines.append(
        "=== SOURCE RAG ==="
    )

    for item in source:

        lines.append(
            "- FILE: "
            + str(
                item.get("path", "")
            )
            + " | score="
            + str(
                item.get("score", "")
            )
        )

        content = str(
            item.get("content", "")
        )

        lines.append(
            content[:2500]
        )

    lines.append("")

    lines.append(
        "=== PRODUCTION KNOWLEDGE AUTHORITY ==="
    )

    lines.append(
        json.dumps(
            summary,
            ensure_ascii=False,
            indent=2,
        )
    )

    # HANYA official/verified menjadi
    # grounding evidence untuk jawaban.
    authoritative = (
        groups["official"]
        + groups["verified"]
    )

    if authoritative:

        lines.append("")

        lines.append(
            "=== AUTHORITATIVE KNOWLEDGE ==="
        )

        for index, item in enumerate(
            authoritative,
            start=1,
        ):

            lines.append(
                f"[AUTHORITY {index}]"
            )

            lines.append(
                "Authority: "
                + str(
                    item.get(
                        "authority"
                    )
                )
            )

            lines.append(
                "Service: "
                + str(
                    item.get(
                        "service"
                    )
                )
            )

            lines.append(
                "Title: "
                + str(
                    item.get(
                        "title"
                    )
                )
            )

            lines.append(
                "Text: "
                + str(
                    item.get(
                        "text"
                    )
                )[:4000]
            )

    else:

        lines.append("")

        lines.append(
            "=== AUTHORITATIVE KNOWLEDGE ==="
        )

        lines.append(
            "TIDAK ADA SUMBER OFFICIAL/VERIFIED."
        )

        lines.append(
            "Jangan membuat klaim pelayanan resmi."
        )

    return (
        "\n".join(lines),
        summary,
    )


