# ============================================================
# GROUNDING GUARD
# ============================================================

STOPWORDS = {
    "yang",
    "dan",
    "atau",
    "untuk",
    "dari",
    "dengan",
    "pada",
    "dalam",
    "adalah",
    "ini",
    "itu",
    "sebagai",
    "ke",
    "di",
    "apa",
    "saya",
    "anda",
    "bisa",
    "dapat",
    "akan",
    "jika",
    "tidak",
    "ada",
    "the",
    "and",
    "for",
    "from",
    "with",
}


def content_tokens(
    text: str,
) -> set[str]:

    words = re.findall(
        r"[a-zA-Z0-9_-]+",
        text.lower(),
    )

    return {
        word
        for word in words
        if len(word) >= 3
        and word not in STOPWORDS
    }


def grounding_guard(
    query: str,
    answer: str,
    authoritative_evidence: list[
        dict[str, Any]
    ],
) -> dict[str, Any]:

    if not answer.strip():

        return {
            "status": "UNSUPPORTED",
            "supported": False,
            "score": 0.0,
            "reason": "Jawaban kosong.",
        }

    evidence_text = " ".join(
        str(
            item.get(
                "text",
                "",
            )
        )
        for item in authoritative_evidence
    )

    # Tidak ada sumber authoritative:
    # model tidak boleh dianggap grounded.
    if not evidence_text.strip():

        return {
            "status": "UNSUPPORTED",
            "supported": False,
            "score": 0.0,
            "reason": (
                "Tidak tersedia evidence "
                "official/verified."
            ),
        }

    evidence_tokens = content_tokens(
        evidence_text
    )

    answer_sentences = [
        sentence.strip()
        for sentence in re.split(
            r"[.!?\n]+",
            answer,
        )
        if sentence.strip()
    ]

    if not answer_sentences:

        return {
            "status": "UNSUPPORTED",
            "supported": False,
            "score": 0.0,
            "reason": "Tidak ada kalimat jawaban.",
        }

    scores: list[float] = []

    for sentence in answer_sentences:

        tokens = content_tokens(
            sentence
        )

        if not tokens:
            continue

        overlap = tokens.intersection(
            evidence_tokens
        )

        score = len(overlap) / max(
            len(tokens),
            1,
        )

        scores.append(score)

    if not scores:

        score = 0.0

    else:

        score = sum(scores) / len(
            scores
        )

    if score >= 0.35:

        status = "GROUNDED"
        supported = True

    elif score >= 0.15:

        status = "PARTIAL"
        supported = False

    else:

        status = "UNSUPPORTED"
        supported = False

    return {
        "status": status,
        "supported": supported,
        "score": round(
            score,
            4,
        ),
        "reason": (
            "Perbandingan token jawaban "
            "dengan authoritative evidence."
        ),
    }


