    while True:

        try:

            if GRAPH_FILE.exists():

                current_mtime = (
                    GRAPH_FILE.stat().st_mtime
                )

                if (
                    previous_mtime is not None
                    and current_mtime
                    != previous_mtime
                ):
                    global _GRAPH_CACHE
                    _GRAPH_CACHE = None

                    print(
                        "[Developer Core] "
                        "Graph berubah. Cache "
                        "dihapus."
                    )

                previous_mtime = (
                    current_mtime
                )

        except Exception as exc:

            print(
                "[Developer Core] "
                "Watcher error:",
                exc,
            )

        time.sleep(15)


