        r = n("read_file", {"success": True, "result": {"success": False, "error": "nf"}})
        self.assertFalse(r["success"]); self.assertEqual(r["error"], "nf")
        self.assertEqual(n("find_file", {"success": True, "result": ["a/b.py"]})["matches"], ["a/b.py"])
